INSERT INTO public.topics (id, title, slug, usmle_step, "order", section, is_free_demo, mcq_count, case_count)
INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, difficulty, "order", type) VALUES
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 58-year-old man presents to the emergency department with 45 minutes of crushing substernal chest pain radiating to the left arm. He is diaphoretic, with blood pressure 150/90 mmHg and heart rate 98/min. ECG shows ST-segment elevation in leads V2-V5. The hospital has a 24-hour catheterization laboratory, and the expected door-to-balloon time is 55 minutes. Which of the following is the most appropriate next step in management?', '["IV tenecteplase now", "Emergent primary PCI", "Urgent CABG", "IV heparin alone and observe", "Transfer to a PCI-capable hospital 3 hours away"]'::jsonb, 1, 'Primary PCI is the preferred reperfusion strategy for STEMI when it can be performed within 120 minutes of first medical contact (door-to-balloon 90 minutes or less); it achieves higher rates of complete reperfusion and lower rates of death, reinfarction, and stroke than fibrinolysis. Fibrinolysis is reserved for when PCI cannot be delivered within 120 minutes. CABG is not first-line for acute STEMI without a mechanical complication or failed PCI. Heparin alone does not restore coronary flow. Transferring three hours away would delay reperfusion far beyond the window and sacrifice myocardium.', 'Medium', 1, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 64-year-old woman arrives at a rural emergency department with 2 hours of severe chest pain. ECG shows ST-segment elevation in leads II, III, and aVF with reciprocal changes in I and aVL. The nearest PCI-capable hospital is 3 hours away. She has no history of bleeding, stroke, or recent surgery, and her blood pressure is 140/85 mmHg. Which of the following is the most appropriate management?', '["IV tenecteplase now, then transfer for coronary angiography within 2-24 hours", "Transfer for primary PCI in 3 hours", "Aspirin and heparin only, without reperfusion", "Urgent CABG", "IV nitroglycerin and observation"]'::jsonb, 0, 'When first-medical-contact-to-device time exceeds 120 minutes, fibrinolysis within 12 hours of symptom onset is indicated (greatest benefit within 3 hours), followed by transfer for coronary angiography within 2-24 hours as a pharmacoinvasive strategy. The STREAM trial and guidelines support this approach, which yields outcomes approaching primary PCI when transfer delays are long. Tenecteplase is preferred as a single-bolus agent, and aspirin, a P2Y12 inhibitor, and anticoagulation accompany lysis, with rescue PCI indicated if reperfusion fails. Waiting 3 hours for PCI loses myocardium. Heparin and aspirin alone do not restore flow. CABG is not first-line for acute STEMI. Nitroglycerin relieves pain but does not reperfuse the occluded artery.', 'Medium', 2, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 71-year-old man presents with 90 minutes of crushing chest pain. ECG shows ST-segment elevation in leads V2-V6 with new Q waves. He had a hemorrhagic stroke 1 year ago. The nearest PCI-capable hospital is 150 minutes away. Which of the following is the most appropriate reperfusion strategy?', '["IV tenecteplase", "IV streptokinase", "No reperfusion, medical therapy only", "Primary PCI despite the delay", "Urgent CABG"]'::jsonb, 3, 'Prior intracranial hemorrhage is an absolute contraindication to fibrinolysis, so tenecteplase and streptokinase are both unsafe in this patient. Other absolute contraindications include prior ischemic stroke within 3 months, known intracranial neoplasm, and active bleeding. Primary PCI is the reperfusion strategy of choice here even though it exceeds 120 minutes, because it avoids bleeding risk and is superior when fibrinolysis is contraindicated; the 120-minute target is a goal, not a reason to withhold reperfusion when lytics cannot be given. Withholding reperfusion entirely sacrifices myocardium and increases mortality. CABG is reserved for failed PCI, mechanical complications, or anatomy unsuitable for PCI, not as initial reperfusion.', 'Medium', 3, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 55-year-old man presents with 1 hour of severe substernal chest pain. His ECG shows ST-segment depression in leads V1-V3 with tall R waves and upright T waves in those leads. Troponin I is elevated. Blood pressure is 145/90 mmHg and he is hemodynamically stable. Which of the following is the most appropriate next step?', '["Treat as NSTEMI with heparin infusion only", "Exercise stress test", "CT angiography of the chest", "Repeat ECG in 6 hours", "Obtain posterior leads V7-V9 and arrange emergent reperfusion"]'::jsonb, 4, 'ST depression in V1-V3 with tall R waves is the mirror image of posterior ST elevation, indicating a posterior STEMI, which is treated as a STEMI with urgent reperfusion; posterior leads V7-V9 confirm the diagnosis, and the infarct is usually due to left circumflex or right coronary occlusion. Missing it is a classic Step 2 trap because the standard 12-lead shows only reciprocal depression. Treating as NSTEMI with heparin alone delays reperfusion and loses myocardium. Stress testing is contraindicated in acute MI. CT angiography is for suspected dissection or pulmonary embolism, not this ECG pattern. Waiting 6 hours to repeat the ECG wastes the reperfusion window.', 'Hard', 4, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 68-year-old man is admitted with non-ST-elevation MI. His troponin is rising, ECG shows dynamic ST-segment depression in the lateral leads, and his GRACE risk score is 152. He is hemodynamically stable with no refractory chest pain. Which of the following is the most appropriate management strategy?', '["Discharge home on aspirin", "Stress test in 48 hours", "Early invasive strategy with coronary angiography within 24 hours", "Medical management only, without angiography", "CABG without coronary angiography"]'::jsonb, 2, 'A GRACE score above 140 defines high risk, and guidelines recommend an early invasive strategy within 24 hours for high-risk NSTEMI with elevated troponin and dynamic ST changes. The GRACE score incorporates age, heart rate, blood pressure, creatinine, Killip class, ST deviation, troponin, and cardiac arrest. Patients with a GRACE score below 140 and no high-risk features can be managed with an ischemia-guided strategy, but this patient meets high-risk criteria, so angiography within 24 hours is the standard. Discharge is unsafe with active ischemia and a rising troponin. Stress testing is not performed in high-risk NSTEMI before angiography. Medical-only management is reserved for low-risk patients or those with prohibitive procedural risk. CABG decisions require angiographic anatomy first.', 'Medium', 5, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 72-year-old woman is admitted with NSTEMI. Despite IV nitroglycerin, she has ongoing refractory chest pain, blood pressure 85/50 mmHg, and runs of nonsustained ventricular tachycardia. Her ECG shows diffuse ST-segment depression. Which of the following is the most appropriate next step?', '["Increase IV nitroglycerin and observe", "Immediate invasive strategy with coronary angiography within 2 hours", "Fibrinolytic therapy", "Dobutamine stress echocardiography", "Discharge on dual antiplatelet therapy"]'::jsonb, 1, 'Refractory angina, hemodynamic instability, and life-threatening arrhythmia are very-high-risk features that mandate an immediate invasive strategy within 2 hours. Very-high-risk criteria also include cardiogenic shock, acute heart failure, and hemodynamically significant arrhythmias, and these patients go to the cath lab immediately rather than waiting for medical stabilization. Delaying for additional medical therapy in this setting increases the risk of death and recurrent MI. Nitrates alone cannot stabilize ongoing ischemia with shock. Fibrinolysis is not indicated for NSTEMI and would not address the culprit lesion. Stress testing is contraindicated with active instability and shock. Discharge is dangerous in a patient with refractory ischemia and ventricular arrhythmia.', 'Medium', 6, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 45-year-old man presents with atypical chest pain that began 3 hours ago. His ECG is normal, and two serial high-sensitivity troponins are negative. His TIMI risk score is 1, and his only risk factor is smoking. He is pain-free now with normal vital signs. Which of the following is the most appropriate next step?', '["Emergent coronary angiography", "IV heparin infusion", "Exercise stress testing before discharge or as a prompt outpatient", "Fibrinolytic therapy", "Urgent CABG"]'::jsonb, 2, 'Low-risk chest pain with negative serial troponins and a normal ECG carries a very low short-term event rate, so stress testing (exercise ECG if the patient can exercise) is appropriate to exclude significant coronary disease before discharge or promptly as an outpatient. A HEART score of 0-3 or TIMI score of 0-1 supports this low-risk pathway, and many such patients can be discharged with close outpatient follow-up if stress testing cannot be done immediately. Emergent angiography is reserved for high-risk ACS. Heparin and fibrinolysis are not indicated without evidence of acute coronary syndrome. CABG requires demonstrated severe anatomy and is never the first step in a low-risk patient.', 'Easy', 7, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 60-year-old man presents with two episodes of chest pain at rest in the last 24 hours, each lasting 15 minutes. His ECG shows T-wave inversions in leads V4-V6. Serial troponins are negative. Blood pressure is 140/85 mmHg and he is currently pain-free. Which of the following is the most likely diagnosis?', '["Unstable angina", "NSTEMI", "Stable angina", "Acute pericarditis", "Aortic dissection"]'::jsonb, 0, 'Rest angina with ischemic ECG changes but negative troponin defines unstable angina, an acute coronary syndrome without myocardial necrosis. Management is the same initial ACS bundle (aspirin, anticoagulation, consideration of a P2Y12 inhibitor and an early invasive strategy if high risk), but the diagnosis hinges on troponin: any elevation reclassifies the patient as NSTEMI. The distinction matters for prognosis and for risk scores, which use troponin as a key variable. Stable angina is exertional and relieved by rest, not pain at rest. Pericarditis causes positional, pleuritic pain with diffuse ST elevation and PR depression, not T-wave inversions. Aortic dissection causes tearing pain radiating to the back with a blood pressure differential and widened mediastinum.', 'Easy', 8, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 62-year-old man is admitted with NSTEMI and is scheduled for percutaneous coronary intervention. He has no history of bleeding or prior stroke, and his renal function is normal. He has received aspirin 325 mg. Which of the following is the most appropriate P2Y12 inhibitor to add?', '["Clopidogrel", "Ticagrelor", "Prasugrel", "GP IIb/IIIa inhibitor alone", "Aspirin alone, no P2Y12 inhibitor"]'::jsonb, 1, 'In acute coronary syndrome, ticagrelor is preferred over clopidogrel because it provides more potent, faster, reversible P2Y12 inhibition and reduced cardiovascular death, MI, and stroke in the PLATO trial without increasing overall major bleeding. Ticagrelor is given as a 180 mg loading dose followed by 90 mg twice daily, and unlike clopidogrel it does not require metabolic activation, so its onset is faster and more predictable. Its main cautions are dyspnea and bradycardia, and it should be stopped 3-5 days before CABG. Clopidogrel is acceptable but slower and less potent. Prasugrel is an alternative for PCI but carries more bleeding risk and has contraindications. A GP IIb/IIIa inhibitor is an IV adjunct, not a substitute for oral P2Y12 therapy. Aspirin alone is insufficient after ACS and PCI.', 'Medium', 9, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 78-year-old man with a prior ischemic stroke 2 years ago is admitted with NSTEMI and is scheduled for PCI. He is already on aspirin. His weight is 68 kg. Which of the following is the most appropriate P2Y12 inhibitor choice?', '["Prasugrel", "Abciximab alone", "Warfarin", "Ticagrelor", "No P2Y12 inhibitor"]'::jsonb, 3, 'Prior stroke or TIA is a contraindication to prasugrel because of excess intracranial bleeding seen in the TRITON-TIMI 38 trial, so ticagrelor is the preferred potent alternative in this patient. Prasugrel is also used cautiously in patients 75 years or older or under 60 kg because of bleeding risk. In such patients ticagrelor or clopidogrel is chosen instead. The loading dose of ticagrelor is 180 mg, and it is continued for at least 12 months after ACS. Abciximab is an IV GP IIb/IIIa adjunct, not a substitute for oral P2Y12 therapy. Warfarin is an anticoagulant, not antiplatelet therapy for ACS. Omitting a P2Y12 inhibitor after PCI leaves the patient at high risk of stent thrombosis.', 'Medium', 10, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 70-year-old woman with NSTEMI was started on fondaparinux. She is now being taken to the catheterization laboratory for PCI. Which of the following is the most appropriate anticoagulation management during the procedure?', '["Continue fondaparinux alone during PCI", "Switch to warfarin", "Stop all anticoagulation", "Give fibrinolytic therapy", "Add an unfractionated heparin bolus during PCI"]'::jsonb, 4, 'Fondaparinux alone during PCI is associated with catheter thrombosis, so guidelines require adding unfractionated heparin at the time of PCI in fondaparinux-treated patients. Fondaparinux is an indirect factor Xa inhibitor that does not inhibit thrombin, which is why catheter thrombosis can occur during PCI; adding unfractionated heparin provides the needed thrombin inhibition. This combination is recommended in the guidelines, whereas fondaparinux is preferred in medically managed NSTEMI because of its lower bleeding risk. Warfarin is not used for acute PCI anticoagulation. Stopping anticoagulation during PCI risks acute thrombosis. Fibrinolysis is not indicated for NSTEMI and would increase bleeding risk during an invasive procedure.', 'Hard', 11, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 74-year-old man with atrial fibrillation on apixaban presents with an acute coronary syndrome and receives a drug-eluting stent. He has no bleeding complications. Which of the following is the most appropriate antithrombotic regimen after PCI?', '["Triple therapy with apixaban, aspirin, and clopidogrel for 12 months", "Dual antiplatelet therapy and stop apixaban", "Warfarin plus dual antiplatelet therapy", "Aspirin plus apixaban only", "Apixaban plus clopidogrel without aspirin"]'::jsonb, 4, 'In atrial fibrillation patients undergoing PCI, dual therapy with a direct oral anticoagulant plus a P2Y12 inhibitor, dropping aspirin early, reduces major bleeding without increasing ischemic events, as shown in the AUGUSTUS and RE-DUAL PCI trials. Aspirin is typically stopped at discharge or within 1 week after PCI in this setting, and the P2Y12 inhibitor (usually clopidogrel) is continued for at least 12 months with the anticoagulant. If bleeding risk is very high, even the P2Y12 inhibitor can be stopped early, but the anticoagulant is continued for stroke prevention. Prolonged triple therapy markedly increases bleeding. Stopping anticoagulation risks stroke. Warfarin-based triple therapy bleeds more than DOAC-based dual therapy. Aspirin plus anticoagulant without a P2Y12 inhibitor leaves the stent unprotected against thrombosis.', 'Hard', 12, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 67-year-old woman is on day 4 after an anterior STEMI. She suddenly becomes hypotensive with blood pressure 70/40 mmHg, develops pulseless electrical activity, and has distended neck veins, muffled heart sounds, and pulsus paradoxus. Which of the following is the most likely diagnosis and immediate management?', '["Free wall rupture with tamponade - IV fluids and pericardiocentesis followed by emergent surgery", "Reinfarction - fibrinolytic therapy", "Pulmonary embolism - IV heparin", "Dressler syndrome - high-dose steroids", "Cardiogenic shock - observation"]'::jsonb, 0, 'Free wall rupture typically occurs 3-5 days after MI, often a first MI in an elderly woman, and causes tamponade with hypotension, elevated jugular venous pressure, muffled heart sounds, pulsus paradoxus, and PEA. Rupture is more common after a first MI with a large transmural infarct and in patients who received late or no reperfusion. Bedside echocardiography confirms pericardial effusion and tamponade physiology. Treatment is pericardiocentesis to relieve tamponade followed by emergent surgical repair, since pericardiocentesis alone is only temporizing. Fibrinolysis would worsen bleeding into the pericardium. Pulmonary embolism presents with tachycardia and clear lungs, not muffled sounds. Dressler syndrome occurs weeks later with fever and pleuritic pain. Observation is fatal.', 'Hard', 13, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 70-year-old man is on day 4 after an acute MI. He develops a new harsh holosystolic murmur best heard at the left sternal border, worsening dyspnea, and pulmonary edema. Right heart catheterization shows an oxygen saturation step-up from the right atrium to the right ventricle. Which of the following is the most likely diagnosis?', '["Papillary muscle rupture", "Free wall rupture", "Ventricular septal rupture", "Dressler syndrome", "Left ventricular aneurysm"]'::jsonb, 2, 'A new harsh holosystolic murmur 3-5 days after MI with an oxygen step-up from right atrium to right ventricle indicates a left-to-right shunt from ventricular septal rupture. Papillary muscle rupture causes acute mitral regurgitation with a murmur at the apex radiating to the axilla and pulmonary edema but no oxygen step-up. Free wall rupture causes tamponade and PEA, not a murmur. Dressler syndrome is pericarditis occurring weeks later. Left ventricular aneurysm presents later with persistent ST elevation and heart failure.', 'Medium', 14, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 66-year-old man is on day 3 after an inferior MI. He develops acute severe dyspnea with pulmonary edema, blood pressure 85/55 mmHg, and a new holosystolic murmur at the apex radiating to the axilla. Chest X-ray shows florid pulmonary edema. Which of the following is the most appropriate immediate management?', '["Fibrinolytic therapy", "Pericardiocentesis", "IV beta-blocker", "Afterload reduction with nitroprusside plus intra-aortic balloon pump and emergent mitral valve surgery", "Observation and diuretics alone"]'::jsonb, 3, 'Papillary muscle rupture, usually the posteromedial muscle after an inferior MI, causes acute severe mitral regurgitation with flash pulmonary edema and shock; definitive treatment is emergent surgery, with nitroprusside to reduce afterload and an intra-aortic balloon pump as a bridge. The posteromedial papillary muscle has a single blood supply from the posterior descending artery, so inferior MI is the classic cause, whereas the anterolateral muscle has dual supply and rarely ruptures. Echocardiography confirms severe mitral regurgitation and a flail leaflet. Fibrinolysis does not repair a mechanical rupture. Pericardiocentesis treats tamponade, not mitral regurgitation. Beta-blockers worsen cardiogenic shock. Diuretics alone cannot stabilize acute severe mitral regurgitation with shock.', 'Hard', 15, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 59-year-old man presents 3 weeks after an acute MI with pleuritic chest pain that worsens when lying flat, low-grade fever, and a pericardial friction rub. ECG shows diffuse concave ST-segment elevation with PR-segment depression, and echocardiography shows a small pericardial effusion. Which of the following is the most appropriate treatment?', '["Urgent PCI", "Pericardiocentesis", "Aspirin or NSAID plus colchicine", "IV heparin infusion", "High-dose corticosteroids as first-line therapy"]'::jsonb, 2, 'Dressler syndrome is post-MI pericarditis, an autoimmune process occurring 2-10 weeks after MI, presenting with pleuritic pain, fever, a friction rub, and diffuse ST elevation; first-line treatment is aspirin or an NSAID plus colchicine. It is thought to result from an immune response to myocardial antigens released after infarction. The ECG shows diffuse concave ST elevation with PR depression, and the effusion is usually small. Colchicine reduces recurrence, and anticoagulation should be avoided because it can worsen pericardial bleeding. Urgent PCI is for acute ischemia, not pericarditis. Pericardiocentesis is for tamponade, not a small effusion. Anticoagulation is not indicated. Steroids are second-line because of relapse risk and are reserved for refractory cases or NSAID contraindications.', 'Medium', 16, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 62-year-old man reports exertional substernal chest pressure that is relieved within minutes by rest. His resting ECG is normal, he is able to walk briskly, and he has no known coronary artery disease. His pretest probability of coronary disease is intermediate. Which of the following is the most appropriate initial test?', '["Coronary CT angiography", "Exercise ECG stress test", "Pharmacologic nuclear stress test", "Diagnostic coronary angiography", "No testing, reassurance only"]'::jsonb, 1, 'For intermediate-risk stable angina in a patient who can exercise with a normal baseline ECG, exercise ECG stress testing is the appropriate first test. The exercise ECG is most useful when the pretest probability is intermediate and the resting ECG is normal without conduction abnormalities, with sensitivity and specificity of roughly 70%. If the patient cannot exercise or has baseline ST abnormalities, imaging-based stress testing is chosen instead. A strongly positive test (early ST depression, hypotension, or poor exercise capacity) prompts angiography. Coronary CT angiography is an alternative for intermediate risk, but exercise ECG is preferred when the patient can exercise. Pharmacologic stress is for patients unable to exercise or with uninterpretable ECGs. Diagnostic angiography is reserved for high-risk features. Reassurance without testing misses significant coronary disease.', 'Easy', 17, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 65-year-old woman reports exertional chest pain. Her baseline ECG shows a left bundle branch block, and she is able to exercise without difficulty. Which of the following is the most appropriate stress test?', '["Exercise ECG stress test", "Coronary CT angiography alone", "Diagnostic coronary angiography first", "No testing needed", "Stress echocardiography or nuclear perfusion imaging"]'::jsonb, 4, 'Left bundle branch block makes the exercise ECG uninterpretable because ST segments cannot be reliably assessed, so stress testing must use imaging, either stress echocardiography or nuclear perfusion imaging. In LBBB, septal depolarization is abnormal, producing ST changes that make exercise ECG interpretation unreliable, and nuclear imaging can show a false-positive septal perfusion defect, so stress echocardiography is often preferred. Pharmacologic stress with dobutamine is used if the patient cannot exercise, and a normal stress echo in this setting carries a very good prognosis. An exercise ECG would be nondiagnostic. CT angiography defines anatomy but does not assess functional significance as well in this setting. Diagnostic angiography is invasive and reserved for high-risk findings. Testing is warranted for exertional angina rather than no evaluation.', 'Medium', 18, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 60-year-old man has stable exertional angina and hypertension. His ejection fraction is normal, and he is not currently on any cardiac medications. Which of the following is the most appropriate first-line antianginal agent?', '["Calcium channel blocker", "Ranolazine", "Beta-blocker", "Digoxin", "Long-acting nitrate alone"]'::jsonb, 2, 'Beta-blockers are first-line antianginal therapy for stable angina because they reduce heart rate and myocardial oxygen demand, and they are especially useful with coexisting hypertension. Beta-blockers also reduce mortality after MI and in heart failure with reduced ejection fraction, adding prognostic benefit beyond symptom relief. If beta-blockers are contraindicated, a calcium channel blocker or long-acting nitrate is used instead. Calcium channel blockers are alternatives or add-on agents. Ranolazine is a second-line add-on therapy, not first-line. Digoxin is not an antianginal drug. Long-acting nitrates relieve symptoms but are not first-line monotherapy for symptom control or prognosis. All patients with stable angina should also receive aspirin and a high-intensity statin for secondary prevention.', 'Easy', 19, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 68-year-old man with stable angina undergoes coronary angiography, which shows 70% stenosis of the left main coronary artery. His ejection fraction is 55% and he has no other significant lesions. Which of the following is the most appropriate treatment?', '["Medical therapy alone", "PCI with drug-eluting stent", "Fibrinolytic therapy", "CABG", "Repeat stress testing"]'::jsonb, 3, 'Significant left main coronary disease carries a survival benefit with CABG, which is the preferred revascularization strategy, especially with multivessel disease or diabetes. The survival benefit of CABG in left main disease was shown in classic trials, and it is greatest with three-vessel disease or reduced ejection fraction. PCI of the left main is reasonable only in selected patients with low SYNTAX scores and anatomy suitable for stenting, after heart-team discussion. Medical therapy alone for significant left main stenosis carries a high mortality. Fibrinolysis is for acute STEMI, not stable disease. Repeat stress testing does not change management once the anatomy is known.', 'Medium', 20, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 48-year-old woman has episodes of chest pain at rest, often at night, with ECG during pain showing transient ST-segment elevation. Coronary angiography shows normal coronary arteries. She smokes one pack of cigarettes daily. Which of the following is the most likely diagnosis and best initial treatment?', '["Variant (Prinzmetal) angina - calcium channel blocker plus nitrate", "Stable angina - beta-blocker", "NSTEMI - dual antiplatelet therapy", "Pericarditis - NSAIDs", "Aortic dissection - urgent surgery"]'::jsonb, 0, 'Chest pain at rest, often nocturnal, with transient ST elevation and normal coronary arteries is coronary vasospasm, or Prinzmetal angina; treatment is a calcium channel blocker with nitrates, plus smoking cessation. Coronary spasm can be provoked by ergonovine or acetylcholine during angiography, but the diagnosis is usually clinical. Triggers include smoking, cocaine, and hyperventilation. Long-acting nitrates and calcium channel blockers prevent episodes, and statins and smoking cessation reduce recurrence. Beta-blockers can worsen spasm by leaving alpha-mediated vasoconstriction unopposed. Dual antiplatelet therapy treats plaque rupture, not spasm. Pericarditis pain is positional with diffuse ECG changes. Aortic dissection causes tearing pain radiating to the back with a blood pressure differential.', 'Medium', 21, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 52-year-old man with confirmed variant angina was started on metoprolol for hypertension. He now reports more frequent episodes of nocturnal chest pain. His ECG during pain shows transient ST-segment elevation. Which of the following is the most appropriate change in management?', '["Increase metoprolol dose", "Add heparin infusion", "Coronary stenting", "Add aspirin only", "Stop the beta-blocker and start a calcium channel blocker"]'::jsonb, 4, 'Beta-blockers can aggravate coronary vasospasm by blocking beta-2-mediated vasodilation and leaving alpha vasoconstriction unopposed, so they should be stopped in variant angina and replaced with a calcium channel blocker, the mainstay of therapy. Beta-blockers are sometimes mistakenly continued because the patient has hypertension, but in variant angina the risk of worsening spasm outweighs any benefit, and hypertension should be treated with a calcium channel blocker instead. Nitrates provide acute relief and prophylaxis. Increasing the beta-blocker dose worsens spasm. Heparin and aspirin do not treat vasospasm. Stenting has no role when the coronary arteries are normal. Patients should also be counseled to stop smoking and avoid cocaine and other vasospastic triggers.', 'Medium', 22, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 45-year-old man has recurrent nocturnal chest pain. During an episode, his ECG shows ST-segment elevation that resolves with nitroglycerin. Coronary angiography is normal. He smokes one pack of cigarettes daily and has no other risk factors. Which of the following is the most appropriate management?', '["Beta-blocker therapy", "CABG", "Dual antiplatelet therapy", "Statin alone", "Smoking cessation plus a calcium channel blocker"]'::jsonb, 4, 'Variant angina is coronary vasospasm, and smoking is a major trigger, so smoking cessation is essential, while calcium channel blockers are first-line therapy along with nitrates. Smoking cessation is the single most important intervention, since tobacco is the strongest trigger for coronary spasm. Calcium channel blockers such as amlodipine or diltiazem are first-line, with long-acting nitrates added if episodes persist. Patients should avoid beta-blockers and be screened for cocaine use, another precipitant of vasospasm. Beta-blockers worsen spasm by leaving alpha-mediated vasoconstriction unopposed. CABG and dual antiplatelet therapy have no role with normal coronary arteries and no plaque rupture. A statin alone does not prevent vasospasm.', 'Easy', 23, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'An 80-year-old woman with septic shock has blood pressure 82/50 mmHg and heart rate 118/min. Her troponin I is 0.8 ng/mL (elevated). She reports no chest pain, and her ECG shows sinus tachycardia without ST-segment changes. Which of the following is the most appropriate management?', '["Treat the underlying sepsis and hypotension", "Emergent PCI", "Fibrinolytic therapy", "Dual antiplatelet therapy plus heparin", "Urgent CABG"]'::jsonb, 0, 'Troponin elevation from a supply-demand mismatch without acute plaque rupture is type 2 MI, and management targets the underlying cause, in this case sepsis and hypotension, rather than reperfusion or dual antiplatelet therapy. Type 2 MI is defined by a supply-demand mismatch causing myocardial injury, with causes including sepsis, hypotension, severe anemia, tachyarrhythmia, hypoxia, and severe hypertension. The troponin rise is real but reflects injury rather than plaque rupture. Treating the precipitant with fluids, vasopressors, and antibiotics is the priority, and long-term management focuses on risk factors. Emergent PCI and fibrinolysis treat type 1 MI from plaque rupture and would expose this patient to bleeding risk without benefit. Urgent CABG has no role without an acute coronary occlusion.', 'Medium', 24, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 55-year-old woman presents with a troponin-positive myocardial infarction. Coronary angiography shows no stenosis greater than 50% and no culprit lesion. Her echocardiogram shows normal left ventricular function. Which of the following is the most appropriate next step?', '["Emergent PCI", "Fibrinolytic therapy", "CABG", "Cardiac MRI", "Discharge without further workup"]'::jsonb, 3, 'Myocardial infarction with non-obstructive coronary arteries (MINOCA) requires evaluation for the underlying cause, such as plaque disruption, coronary spasm, embolism, spontaneous dissection, myocarditis, or Takotsubo cardiomyopathy. Cardiac MRI with late gadolinium enhancement distinguishes ischemic injury (subendocardial or transmural) from myocarditis (mid-wall or epicardial) and Takotsubo (no enhancement with apical ballooning). Intravascular ultrasound or optical coherence tomography can identify plaque disruption missed on angiography. Treatment is tailored to the cause, including calcium channel blockers for spasm and guideline therapy for plaque disruption. PCI, fibrinolysis, and CABG have no target lesion to treat. Discharge without workup misses treatable causes and leaves the diagnosis unexplained.', 'Hard', 25, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 72-year-old man with known coronary artery disease presents with chest pain and a hemoglobin of 6.5 g/dL from acute gastrointestinal bleeding. His troponin is elevated, and his ECG shows diffuse ST-segment depression. An angiogram from last year showed a stable 50% LAD lesion. Which of the following is the most likely mechanism and appropriate management?', '["Emergent PCI", "Blood transfusion and treatment of the underlying cause", "Fibrinolytic therapy", "Dual antiplatelet loading", "Urgent CABG"]'::jsonb, 1, 'Severe anemia causing a supply-demand mismatch is type 2 MI, so the priority is blood transfusion and stopping the bleed, not reperfusion. The mechanism is a supply-demand mismatch: severe anemia reduces oxygen delivery while tachycardia and increased demand raise myocardial oxygen consumption. The troponin elevation reflects injury, not plaque rupture. Management is transfusion to a hemoglobin above 7-8 g/dL (higher with ongoing ischemia), control of bleeding, and treatment of the underlying cause. There is no acute plaque rupture to stent, and fibrinolysis would worsen bleeding. Dual antiplatelet loading is not indicated without plaque rupture and increases bleeding risk. CABG is not indicated for stable chronic coronary disease.', 'Medium', 26, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 60-year-old man is 1 week after an anterior STEMI. His ejection fraction is 35%. He is taking aspirin, ticagrelor, and atorvastatin 80 mg daily. His blood pressure is 130/80 mmHg and heart rate is 72/min. Which of the following is the most appropriate additional therapy?', '["Add warfarin", "Stop ticagrelor", "Add a beta-blocker and an ACE inhibitor", "Add a calcium channel blocker", "Stop the statin"]'::jsonb, 2, 'After MI with reduced ejection fraction, a beta-blocker and an ACE inhibitor are indicated for mortality benefit and prevention of adverse remodeling, in addition to dual antiplatelet therapy and high-intensity statin. ACE inhibitors are especially indicated with anterior MI, reduced ejection fraction, hypertension, or diabetes, and they reduce remodeling and mortality. Beta-blockers reduce arrhythmia and reinfarction. High-intensity statin, dual antiplatelet therapy for at least 12 months, and cardiac rehabilitation complete the secondary prevention bundle. Warfarin is not indicated without another indication such as atrial fibrillation or left ventricular thrombus. Stopping ticagrelor risks stent thrombosis. Calcium channel blockers do not improve post-MI outcomes and can worsen heart failure. Statins are continued lifelong.', 'Medium', 27, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 65-year-old man is 2 weeks after an MI. He is hemodynamically stable, has completed his inpatient recovery, and asks about exercise and returning to activity. His ejection fraction is 45%. Which of the following is the most appropriate recommendation?', '["Strict bed rest for 6 weeks", "Avoid all exercise indefinitely", "Rehabilitation only if the ejection fraction is normal", "Enroll in a supervised cardiac rehabilitation program", "No rehabilitation is needed after MI"]'::jsonb, 3, 'Cardiac rehabilitation, including supervised exercise, risk-factor counseling, and psychosocial support, reduces mortality and readmissions after MI and is recommended for all eligible patients regardless of ejection fraction. Cardiac rehabilitation is a Class I recommendation after MI and PCI, with programs typically running 12 weeks and including monitored exercise, dietary counseling, smoking cessation, and psychosocial support. Benefits include reduced mortality, fewer readmissions, and better functional capacity. It is safe and beneficial even in patients with reduced ejection fraction. Bed rest and exercise avoidance cause deconditioning and worsen outcomes. Rehabilitation benefits patients with reduced ejection fraction as well. Declining rehabilitation forgoes a proven mortality benefit.', 'Easy', 28, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 58-year-old woman is 12 months after an acute coronary syndrome treated with a drug-eluting stent. She has had no bleeding episodes. She has diabetes and a prior MI, giving her high ischemic risk, and low bleeding risk. Which of the following is the most appropriate next step regarding antiplatelet therapy?', '["Stop the P2Y12 inhibitor now", "Continue dual antiplatelet therapy beyond 12 months", "Switch to warfarin", "Stop aspirin and continue P2Y12 alone", "Stop both antiplatelet agents"]'::jsonb, 1, 'After ACS with PCI, dual antiplatelet therapy is given for at least 12 months, and in patients with high ischemic risk and low bleeding risk, extended therapy beyond 12 months further reduces ischemic events. The decision balances ischemic risk against bleeding risk: diabetes, prior MI, multivessel disease, and complex PCI favor extension, while bleeding history favors stopping. The DAPT score helps quantify this trade-off. If extended therapy is chosen, the P2Y12 inhibitor is usually ticagrelor 60 mg twice daily or continued clopidogrel. Stopping at 12 months is reasonable for average risk but not optimal here. Warfarin is not a substitute for antiplatelet therapy. Stopping aspirin or all antiplatelet therapy increases the risk of stent thrombosis and recurrent MI.', 'Medium', 29, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 63-year-old man is 2 weeks after a large anterior MI. Echocardiography shows an apical left ventricular thrombus, and his ejection fraction is 30%. He is taking aspirin and ticagrelor and has no bleeding. Which of the following is the most appropriate management?', '["Warfarin for at least 3 months", "Apixaban alone", "No anticoagulation", "Surgical thrombectomy", "Fibrinolytic therapy"]'::jsonb, 0, 'Left ventricular thrombus after an anterior MI requires anticoagulation to prevent systemic embolization, and warfarin for at least 3 months with repeat imaging is the established therapy. Thrombus forms in areas of akinesis after a large anterior MI, especially at the apex, and can embolize to the brain or periphery. Warfarin with an INR of 2-3 is the standard, continued for at least 3 months and until repeat imaging shows resolution. Direct oral anticoagulants are not yet standard for left ventricular thrombus. No anticoagulation risks stroke and peripheral embolism. Surgery is reserved for mobile thrombus with embolic events or refractory cases. Fibrinolysis does not safely dissolve organized left ventricular thrombus.', 'Medium', 30, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 64-year-old man with ischemic cardiomyopathy presents for follow-up. He has an ejection fraction of 28% and NYHA class II symptoms despite 3 months of lisinopril 10 mg daily and metoprolol succinate 50 mg daily. His blood pressure is 118/74 mmHg, heart rate 72/min, serum potassium 4.2 mEq/L, and eGFR 58 mL/min/1.73 m2. He reports mild dyspnea on exertion but no orthopnea or edema. Which of the following is the most appropriate next step in management?', '["Discontinue metoprolol and start digoxin", "Add hydralazine-isosorbide dinitrate", "Add amlodipine", "Add spironolactone", "Refer for cardiac transplantation evaluation"]'::jsonb, 3, 'Spironolactone, a mineralocorticoid receptor antagonist (MRA), is a pillar of guideline-directed medical therapy for HFrEF with EF 35% or less and NYHA class II-IV symptoms, reducing mortality and hospitalizations when potassium and renal function allow. Digoxin reduces hospitalizations but not mortality and is not a next step before an MRA. Hydralazine-isosorbide dinitrate is reserved for Black patients with persistent symptoms or those intolerant of ACE inhibitors/ARNI. Amlodipine does not improve HFrEF outcomes. Transplant evaluation is premature for a stable NYHA II patient on incomplete GDMT.', 'Medium', 31, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 58-year-old woman with nonischemic dilated cardiomyopathy has an ejection fraction of 30% and NYHA class II symptoms. She takes lisinopril 10 mg daily and carvedilol 12.5 mg twice daily, and her blood pressure is 112/70 mmHg with a heart rate of 68/min. Her potassium is 4.4 mEq/L and creatinine is 1.0 mg/dL. She continues to have exertional dyspnea. Which of the following is the most appropriate next step in management?', '["Add verapamil", "Increase lisinopril to 20 mg daily", "Add furosemide 40 mg daily", "Add ivabradine", "Replace lisinopril with sacubitril-valsartan"]'::jsonb, 4, 'Sacubitril-valsartan (ARNI) is preferred over an ACE inhibitor in symptomatic HFrEF (EF 40% or less, NYHA II-IV) because it reduces cardiovascular death and heart failure hospitalizations compared with enalapril, provided blood pressure and renal function allow and there is a 36-hour ACE inhibitor washout. Simply increasing the ACE inhibitor dose does not confer the added neprilysin-inhibition benefit. Furosemide relieves congestion but does not modify mortality. Ivabradine is only indicated with sinus rhythm, heart rate 70/min or higher, and persistent symptoms on maximally tolerated beta-blocker. Verapamil is contraindicated in HFrEF due to negative inotropy.', 'Medium', 32, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 62-year-old man with type 2 diabetes mellitus and HFrEF with an ejection fraction of 32% is on sacubitril-valsartan, metoprolol succinate, and spironolactone at target doses. He remains NYHA class II with occasional exertional dyspnea. His blood pressure is 116/72 mmHg, eGFR 52 mL/min/1.73 m2, and HbA1c 7.4%. Which of the following is the most appropriate next step in management?', '["Add empagliflozin", "Add digoxin", "Add isosorbide dinitrate alone", "Switch metoprolol to diltiazem", "Add aliskiren"]'::jsonb, 0, 'SGLT2 inhibitors such as empagliflozin and dapagliflozin are a fourth pillar of HFrEF GDMT, reducing cardiovascular death and heart failure hospitalizations regardless of diabetes status, and remain effective down to an eGFR of 20 mL/min/1.73 m2. Digoxin reduces hospitalizations only and is not a mortality-reducing GDMT pillar. Isosorbide dinitrate alone without hydralazine has no established role. Diltiazem is contraindicated in HFrEF due to negative inotropy. Aliskiren, a direct renin inhibitor, is not part of GDMT and adds no benefit when combined with ACE inhibition.', 'Medium', 33, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 71-year-old man with HFrEF (ejection fraction 30%) is seen in clinic. He is on sacubitril-valsartan and metoprolol succinate. His potassium is 5.9 mEq/L, creatinine 1.9 mg/dL (eGFR 32 mL/min/1.73 m2), and blood pressure 108/66 mmHg. He has mild lower extremity edema and NYHA class III symptoms. Which of the following is the most appropriate management decision regarding his guideline-directed therapy?', '["Add spironolactone for further mortality benefit", "Increase the sacubitril-valsartan dose", "Withhold mineralocorticoid receptor antagonist therapy because of hyperkalemia and renal dysfunction", "Stop metoprolol because of low blood pressure", "Add amiloride to lower potassium"]'::jsonb, 2, 'MRAs are contraindicated when potassium exceeds 5.0 mEq/L or eGFR falls below 30 mL/min/1.73 m2 (and should be used cautiously with potassium above 5.0), because they worsen hyperkalemia and renal dysfunction; this patient has both problems, so an MRA must be withheld and potassium addressed. Increasing ARNI would worsen renal function and hyperkalemia. Metoprolol should not be stopped for a systolic pressure of 108 mmHg in a compensated patient, since beta-blockers reduce mortality. Amiloride is itself a potassium-sparing diuretic and would worsen hyperkalemia.', 'Hard', 34, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 72-year-old woman with long-standing hypertension, type 2 diabetes, and atrial fibrillation presents with progressive exertional dyspnea, orthopnea, and bilateral leg edema over 3 months. Her blood pressure is 158/88 mmHg and heart rate is 92/min and irregular. Echocardiography shows a left ventricular ejection fraction of 58%, left atrial enlargement, left ventricular hypertrophy, and an elevated E/e'' ratio with grade II diastolic dysfunction. Her BNP is 640 pg/mL. Which of the following is the most likely diagnosis?', '["Heart failure with reduced ejection fraction", "Cardiac tamponade", "Heart failure with preserved ejection fraction", "Acute mitral regurgitation", "Pulmonary embolism"]'::jsonb, 2, 'HFpEF is defined by heart failure symptoms with a preserved ejection fraction of 50% or greater, plus objective evidence of diastolic dysfunction or elevated filling pressures; this patient has typical risk factors (hypertension, diabetes, atrial fibrillation), a normal EF, left atrial enlargement, and elevated E/e'' and BNP. HFrEF requires an EF of 40% or less. Tamponade causes hypotension, pulsus paradoxus, and a pericardial effusion, none of which are present. Acute mitral regurgitation would show a flail leaflet and a new murmur with pulmonary edema. Pulmonary embolism causes acute dyspnea and hypoxia, not chronic orthopnea with diastolic dysfunction.', 'Medium', 35, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 68-year-old woman with HFpEF (ejection fraction 55%), hypertension, and type 2 diabetes is hospitalized for acute decompensated heart failure with pulmonary congestion. After diuresis she is euvolemic and ready for discharge. Her eGFR is 48 mL/min/1.73 m2 and potassium is 4.3 mEq/L. Which of the following medications has been shown to reduce heart failure hospitalizations in HFpEF and should be started before discharge?', '["Sacubitril-valsartan", "Digoxin", "Spironolactone", "Dapagliflozin", "Isosorbide dinitrate"]'::jsonb, 3, 'SGLT2 inhibitors such as dapagliflozin and empagliflozin reduce the composite of cardiovascular death or heart failure hospitalization in HFpEF (ejection fraction 40% or greater) regardless of diabetes status, making them the only drug class with a clear outcome benefit in this population, as shown in the EMPEROR-Preserved and DELIVER-HF trials. Sacubitril-valsartan showed only a borderline, non-significant benefit in HFpEF trials. Spironolactone has conflicting evidence and is not guideline-recommended as a primary HFpEF therapy. Digoxin does not improve outcomes in HFpEF. Isosorbide dinitrate has no role in HFpEF management, and loop diuretics remain the mainstay for relieving congestion rather than modifying prognosis.', 'Hard', 36, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 76-year-old man with HFpEF, hypertension, and chronic kidney disease presents with 3 days of worsening dyspnea, orthopnea, and weight gain of 4 kg. His blood pressure is 168/92 mmHg, heart rate 88/min, oxygen saturation 91% on room air, and he has bilateral crackles and 2+ pitting edema. Echocardiography shows an ejection fraction of 60% with diastolic dysfunction. Which of the following is the most appropriate initial management?', '["Intravenous furosemide", "Intravenous metoprolol", "Oral sacubitril-valsartan", "Intravenous dobutamine", "Oral amlodipine"]'::jsonb, 0, 'Intravenous loop diuretics are first-line therapy for acute decompensated heart failure with volume overload in both HFrEF and HFpEF, relieving congestion and improving dyspnea, and they work regardless of ejection fraction because the problem is congestion rather than contractility. Intravenous metoprolol is inappropriate during acute decompensation and can worsen hemodynamics by reducing cardiac output. Sacubitril-valsartan is a chronic therapy with no proven mortality benefit in HFpEF and is not used acutely. Dobutamine is reserved for cardiogenic shock or low-output states with hypoperfusion, not for a hypertensive, congested patient. Amlodipine does not relieve acute congestion and has no role in acute heart failure.', 'Easy', 37, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 70-year-old man with a history of heart failure presents to the emergency department with severe dyspnea, pink frothy sputum, and diaphoresis. His blood pressure is 185/110 mmHg, heart rate 118/min, respiratory rate 28/min, and oxygen saturation 86% on room air. Chest auscultation reveals diffuse crackles, and chest radiograph shows bilateral pulmonary edema. Which of the following is the most appropriate initial treatment?', '["Intravenous morphine", "Intravenous furosemide", "Intravenous dobutamine", "Oral spironolactone", "Intravenous amiodarone"]'::jsonb, 1, 'Intravenous loop diuretics, typically furosemide, are the cornerstone of acute pulmonary edema management, rapidly reducing preload and relieving congestion; noninvasive positive pressure ventilation and nitrates are adjuncts when blood pressure allows, and patients should be sat upright with oxygen as needed. Morphine is no longer recommended due to worse outcomes and respiratory depression. Dobutamine is indicated only for cardiogenic shock or low-output hypoperfusion, not for a hypertensive patient with pulmonary edema. Oral spironolactone acts too slowly for acute decompensation. Amiodarone treats arrhythmias and has no role here.', 'Easy', 38, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 66-year-old woman with HFrEF is admitted with acute decompensated heart failure. She has received 80 mg of intravenous furosemide twice daily for 24 hours but remains congested with persistent dyspnea, orthopnea, and a weight loss of only 0.5 kg. Her blood pressure is 150/90 mmHg, creatinine has risen from 1.1 to 1.4 mg/dL, and urine output is 600 mL in the last 24 hours. Which of the following is the most appropriate next step in management?', '["Add intravenous dobutamine", "Add intravenous metoprolol", "Switch to oral furosemide", "Add intravenous nitroglycerin", "Stop all diuretics because of rising creatinine"]'::jsonb, 3, 'Intravenous nitroglycerin is a vasodilator that reduces preload and afterload and is appropriate for a congested patient with adequate blood pressure who has not responded to diuretics, improving dyspnea and filling pressures. Dobutamine is reserved for hypoperfusion or cardiogenic shock, which this patient does not have. Switching to oral furosemide would reduce bioavailability and worsen diuretic resistance. Intravenous beta-blockers are contraindicated in acute decompensation. A modest creatinine rise during effective decongestion is common and should not prompt stopping diuretics while congestion persists.', 'Hard', 39, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 59-year-old man with HFrEF (ejection fraction 25%) is admitted with worsening dyspnea, fatigue, and cool extremities. His blood pressure is 82/58 mmHg, heart rate 112/min, and he has a narrow pulse pressure. Labs show a lactate of 4.2 mmol/L, creatinine 2.1 mg/dL, and elevated liver enzymes. Despite intravenous furosemide, his urine output is 15 mL/hour and mentation is declining. Which of the following is the most appropriate next step in management?', '["Increase the furosemide dose", "Start intravenous dobutamine", "Start intravenous nitroglycerin", "Start oral sacubitril-valsartan", "Start intravenous metoprolol"]'::jsonb, 1, 'This patient has cardiogenic shock with hypoperfusion (hypotension, elevated lactate, oliguria, altered mentation, cool extremities) despite diuresis, so an inotrope such as dobutamine is indicated to restore cardiac output and end-organ perfusion, usually in combination with a vasopressor such as norepinephrine if hypotension persists. More furosemide would worsen perfusion in a low-output state by further reducing preload. Nitroglycerin would further lower blood pressure and is contraindicated in shock. Sacubitril-valsartan is a chronic oral therapy that lowers blood pressure and has no role in acute shock. Beta-blockers reduce contractility and are contraindicated in decompensated shock.', 'Medium', 40, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 63-year-old man presents to the emergency department 6 hours after the onset of severe crushing chest pain. His blood pressure is 78/50 mmHg, heart rate 122/min, and he is cool, clammy, and confused. Bedside echocardiography shows an ejection fraction of 25% with anterior wall akinesis and no pericardial effusion. ECG shows ST elevations in leads V2-V5. Labs reveal a lactate of 5.1 mmol/L and creatinine 1.8 mg/dL. Which of the following is the most likely diagnosis?', '["Septic shock", "Hypovolemic shock", "Massive pulmonary embolism", "Cardiac tamponade", "Cardiogenic shock"]'::jsonb, 4, 'Cardiogenic shock is a low-output state from pump failure, classically after a large anterior myocardial infarction, presenting with hypotension, cool clammy extremities, altered mentation, elevated lactate, and a low ejection fraction with regional wall motion abnormality. Septic shock typically features warm extremities, fever, and a source of infection. Hypovolemic shock follows volume loss and shows a hyperdynamic, underfilled ventricle. Massive pulmonary embolism causes right ventricular strain and a dilated right ventricle, not anterior akinesis. Tamponade would show a pericardial effusion with chamber collapse on echo, which is absent here.', 'Medium', 41, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 58-year-old woman with a large anterior ST-elevation myocardial infarction develops cardiogenic shock. Her blood pressure is 74/48 mmHg despite intravenous fluids, and she has evidence of end-organ hypoperfusion with a lactate of 4.8 mmol/L. She is taken for emergent percutaneous coronary intervention of the left anterior descending artery. Which of the following is the most appropriate first-line vasopressor to support her blood pressure?', '["Epinephrine", "Dopamine", "Phenylephrine", "Vasopressin", "Norepinephrine"]'::jsonb, 4, 'Norepinephrine is the first-line vasopressor in cardiogenic shock because it raises blood pressure with less arrhythmia and less mortality than dopamine, and it preserves coronary perfusion pressure; the SOAP II trial showed higher mortality and more arrhythmias with dopamine in the cardiogenic shock subgroup. Dopamine causes more tachyarrhythmias and is associated with higher mortality in cardiogenic shock. Phenylephrine is a pure alpha agonist that increases afterload without inotropy and can worsen cardiac output. Vasopressin is a second-line adjunct, not first-line. Epinephrine is reserved for refractory shock because of lactic acidosis and arrhythmia risk.', 'Medium', 42, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 66-year-old man with cardiogenic shock after an anterior myocardial infarction remains hypotensive with a cardiac index of 1.7 L/min/m2 and a pulmonary capillary wedge pressure of 24 mmHg despite norepinephrine and dobutamine. He has progressive lactic acidosis and oliguria. The cardiology team discusses mechanical circulatory support. Which of the following is the most appropriate statement regarding mechanical support in this setting?', '["An intra-aortic balloon pump is routinely recommended for all patients with cardiogenic shock", "Temporary mechanical circulatory support with a percutaneous ventricular assist device may be considered as a bridge to recovery or decision", "Mechanical support is contraindicated after myocardial infarction", "An intra-aortic balloon pump is the only device with proven mortality benefit", "Vasodilator therapy alone is superior to mechanical support"]'::jsonb, 1, 'Temporary percutaneous mechanical circulatory support (such as Impella or venoarterial ECMO) may be considered in selected patients with refractory cardiogenic shock as a bridge to recovery, durable support, or transplant, though routine use has not shown a clear mortality benefit in trials. The intra-aortic balloon pump is not routinely recommended, as the IABP-SHOCK II trial showed no mortality benefit. Mechanical support is not contraindicated after MI; it is most commonly used in this setting. No mechanical device has a proven mortality benefit in cardiogenic shock. Vasodilators alone cannot restore output in refractory shock.', 'Hard', 43, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 48-year-old man presents with 6 months of progressive exertional dyspnea, orthopnea, and ankle swelling. He drinks approximately 8-10 beers daily for the past 15 years and has no history of hypertension or coronary disease. Examination shows jugular venous distension, a displaced apical impulse, an S3 gallop, and bilateral pitting edema. Echocardiography shows a dilated left ventricle with an ejection fraction of 25% and no significant valvular disease. Which of the following is the most likely cause of his cardiomyopathy?', '["Hypertrophic cardiomyopathy", "Arrhythmogenic right ventricular cardiomyopathy", "Cardiac amyloidosis", "Alcoholic cardiomyopathy", "Takotsubo cardiomyopathy"]'::jsonb, 3, 'Alcoholic cardiomyopathy is a toxic dilated cardiomyopathy caused by chronic heavy alcohol use, presenting with a dilated, poorly contractile left ventricle and biventricular heart failure; abstinence can partially reverse the dysfunction. Hypertrophic cardiomyopathy shows a thickened, nondilated ventricle with a hyperdynamic ejection fraction. Cardiac amyloidosis causes a restrictive pattern with thick walls, low voltage on ECG, and small ventricles. Arrhythmogenic right ventricular cardiomyopathy predominantly affects the right ventricle with ventricular arrhythmias. Takotsubo cardiomyopathy is an acute, stress-triggered, transient apical ballooning syndrome, not a chronic dilated ventricle.', 'Easy', 44, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 31-year-old woman presents 3 weeks after an uncomplicated vaginal delivery with worsening dyspnea, orthopnea, and fatigue. She has no prior cardiac history. Her blood pressure is 110/70 mmHg, heart rate 108/min, and examination shows bibasilar crackles, jugular venous distension, and 2+ leg edema. Echocardiography reveals a left ventricular ejection fraction of 30% with global hypokinesis and left ventricular dilation. Which of the following is the most likely diagnosis?', '["Pulmonary embolism", "Acute coronary syndrome", "Peripartum cardiomyopathy", "Postpartum thyroiditis", "Amniotic fluid embolism"]'::jsonb, 2, 'Peripartum cardiomyopathy is a dilated cardiomyopathy presenting with heart failure in the last month of pregnancy or within 5 months postpartum, with an ejection fraction below 45% and no other identifiable cause; it typically presents 2-4 weeks postpartum as here. Pulmonary embolism causes acute dyspnea with pleuritic pain and tachycardia but not a reduced ejection fraction with global hypokinesis. Acute coronary syndrome is uncommon in this age group without risk factors and would show regional wall motion abnormality. Postpartum thyroiditis causes thyrotoxicosis symptoms, not systolic dysfunction. Amniotic fluid embolism presents acutely during labor or delivery with cardiovascular collapse and disseminated intravascular coagulation.', 'Medium', 45, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 42-year-old man presents with 2 months of progressive dyspnea and fatigue. Three weeks ago he had a febrile illness with sore throat, myalgias, and diarrhea. Echocardiography shows a dilated left ventricle with an ejection fraction of 32% and global hypokinesis. Coronary angiography is normal. Cardiac MRI shows patchy late gadolinium enhancement and myocardial edema. Which of the following is the most likely underlying cause of his dilated cardiomyopathy?', '["Viral myocarditis", "Ischemic cardiomyopathy", "Hypertensive heart disease", "Hemochromatosis", "Sarcoidosis"]'::jsonb, 0, 'Viral myocarditis, most commonly from coxsackievirus, adenovirus, or parvovirus B19, follows a viral prodrome and can progress to dilated cardiomyopathy; cardiac MRI showing edema and late gadolinium enhancement supports the diagnosis. Ischemic cardiomyopathy is excluded by normal coronary angiography. Hypertensive heart disease causes concentric hypertrophy, not a dilated ventricle. Hemochromatosis causes iron overload with a restrictive or dilated pattern but would show iron deposition on MRI and systemic features. Sarcoidosis typically causes patchy basal septal thinning, conduction disease, and ventricular arrhythmias rather than diffuse dilation after a viral illness.', 'Medium', 46, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 24-year-old man presents with exertional syncope. On examination he has a harsh crescendo-decrescendo systolic murmur best heard at the left sternal border that becomes louder with Valsalva maneuver and softer with squatting. Echocardiography shows asymmetric septal hypertrophy of 22 mm with systolic anterior motion of the mitral valve and a left ventricular outflow tract gradient of 55 mmHg. Which of the following is the most likely diagnosis?', '["Aortic stenosis", "Mitral valve prolapse", "Aortic regurgitation", "Dilated cardiomyopathy", "Hypertrophic cardiomyopathy"]'::jsonb, 4, 'Hypertrophic cardiomyopathy is characterized by asymmetric septal hypertrophy with dynamic left ventricular outflow tract obstruction; the murmur intensifies with maneuvers that decrease preload or afterload (Valsalva, standing) and softens with increased preload or afterload (squatting, handgrip), distinguishing it from fixed valvular lesions. Aortic stenosis murmur decreases with Valsalva and increases with squatting, the opposite pattern. Mitral valve prolapse causes a mid-systolic click and late systolic murmur. Dilated cardiomyopathy presents with a dilated ventricle and low ejection fraction. Aortic regurgitation causes a diastolic murmur, not a systolic ejection murmur.', 'Medium', 47, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 19-year-old college basketball player with hypertrophic cardiomyopathy is evaluated for sudden cardiac death risk. He has a maximal left ventricular wall thickness of 32 mm, a history of unexplained syncope last year, and nonsustained ventricular tachycardia on Holter monitoring. His father died suddenly at age 42. Which of the following is the most appropriate management?', '["Reassurance and annual follow-up", "Implantable cardioverter-defibrillator placement", "Amiodarone therapy alone", "Surgical myectomy", "Alcohol septal ablation"]'::jsonb, 1, 'An implantable cardioverter-defibrillator is indicated for primary prevention in hypertrophic cardiomyopathy when major risk factors are present, including massive wall thickness of 30 mm or greater, unexplained syncope, nonsustained ventricular tachycardia, and family history of sudden death; this patient has all four. Reassurance is inappropriate given multiple high-risk features. Amiodarone alone does not prevent sudden death and is not a substitute for an ICD. Surgical myectomy and alcohol septal ablation relieve outflow tract obstruction in symptomatic patients but do not prevent sudden cardiac death.', 'Hard', 48, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 45-year-old man with hypertrophic cardiomyopathy and a resting left ventricular outflow tract gradient of 60 mmHg has progressive exertional dyspnea and chest pain. He is currently on no cardiac medications. His blood pressure is 128/78 mmHg and heart rate is 76/min. Which of the following is the most appropriate initial treatment?', '["Nitroglycerin as needed for chest pain", "Intravenous furosemide", "Digoxin", "A beta-blocker such as metoprolol", "Nifedipine"]'::jsonb, 3, 'Beta-blockers are first-line therapy for symptomatic obstructive hypertrophic cardiomyopathy because they reduce heart rate, prolong diastole, and decrease the outflow tract gradient by reducing contractility, and patients should also avoid strenuous exercise and dehydration. Nitrates reduce preload and worsen outflow obstruction, so they are contraindicated. Diuretics reduce preload and worsen obstruction. Digoxin increases contractility and worsens the gradient. Nifedipine, a dihydropyridine calcium channel blocker, causes vasodilation and reflex tachycardia that can worsen obstruction; verapamil is the alternative when beta-blockers are not tolerated, and mavacamten is a newer option for refractory symptoms.', 'Medium', 49, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 58-year-old woman with a history of breast cancer treated with radiation presents with progressive dyspnea, fatigue, and peripheral edema. Examination shows elevated jugular venous pressure with a prominent y descent, Kussmaul sign, and a pericardial knock. Echocardiography shows normal left ventricular wall thickness with biatrial enlargement and a restrictive filling pattern. Cardiac catheterization shows equalization of diastolic pressures in all four chambers with a dip-and-plateau waveform. Which of the following best distinguishes constrictive pericarditis from restrictive cardiomyopathy in this patient?', '["Presence of Kussmaul sign", "Equalization of diastolic pressures", "Preserved tissue Doppler e'' velocity", "Dip-and-plateau waveform", "Elevated jugular venous pressure"]'::jsonb, 2, 'Tissue Doppler imaging of the mitral annulus shows a preserved or even exaggerated early diastolic velocity (e'') in constrictive pericarditis because the myocardium itself is normal, whereas e'' is reduced in restrictive cardiomyopathy due to intrinsic myocardial disease; this is the most reliable echocardiographic discriminator. Kussmaul sign, equalization of diastolic pressures, dip-and-plateau waveform, and elevated jugular venous pressure occur in both conditions and do not distinguish them. In this patient, prior radiation favors constrictive pericarditis, and a preserved e'' would support that diagnosis.', 'Hard', 50, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 67-year-old man with cardiac amyloidosis presents with progressive dyspnea, peripheral edema, and fatigue. Echocardiography shows markedly increased left ventricular wall thickness with a small left ventricular cavity, biatrial enlargement, and a restrictive filling pattern with an ejection fraction of 50%. ECG shows low QRS voltage despite the thick walls, and he has first-degree atrioventricular block. Which of the following is the most likely diagnosis?', '["Restrictive cardiomyopathy due to cardiac amyloidosis", "Hypertrophic cardiomyopathy", "Constrictive pericarditis", "Dilated cardiomyopathy", "Hypertensive heart disease"]'::jsonb, 0, 'Cardiac amyloidosis causes a restrictive cardiomyopathy with thick ventricular walls, small cavities, biatrial enlargement, and low voltage on ECG despite the apparent hypertrophy, a classic voltage-mass mismatch, often with conduction disease. Hypertrophic cardiomyopathy shows high voltage on ECG and asymmetric septal hypertrophy with a hyperdynamic ventricle. Constrictive pericarditis shows a normal-thickness myocardium with pericardial thickening and preserved tissue Doppler e''. Dilated cardiomyopathy shows a dilated ventricle with a low ejection fraction. Hypertensive heart disease causes concentric hypertrophy with normal or high ECG voltage, not low voltage.', 'Medium', 51, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 55-year-old man with a history of tuberculosis presents with progressive dyspnea, fatigue, and marked peripheral edema over 6 months. Examination shows jugular venous distension, a pericardial knock, and hepatomegaly. Echocardiography shows a thickened pericardium with septal bounce and preserved tissue Doppler e'' velocity. Chest radiograph shows pericardial calcification. Which of the following is the most appropriate definitive treatment?', '["Intravenous furosemide alone", "Heart transplantation", "Pericardiocentesis", "High-dose corticosteroids", "Pericardiectomy"]'::jsonb, 4, 'Constrictive pericarditis from a rigid, scarred, calcified pericardium is definitively treated with surgical pericardiectomy, which removes the constricting pericardium and restores diastolic filling; diuretics provide only temporary symptomatic relief and can be used as a bridge to surgery but do not address the underlying constraint. Pericardiocentesis drains pericardial fluid and is used for tamponade, not for a thickened, calcified pericardium without effusion. Corticosteroids are used for acute pericarditis, not chronic constriction. Heart transplantation is not indicated when the myocardium is normal and the problem is extrinsic pericardial constraint.', 'Medium', 52, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 28-year-old man presents with 2 days of sharp retrosternal chest pain that worsens when lying flat and improves when sitting forward, along with low-grade fever and malaise. He had a viral upper respiratory infection 1 week ago. ECG shows diffuse ST-segment elevation with PR-segment depression. Troponin I is elevated at 2.4 ng/mL. Echocardiography shows a normal ejection fraction with a small pericardial effusion and no wall motion abnormality. Which of the following is the most likely diagnosis?', '["Acute pericarditis", "Acute myocardial infarction", "Acute myocarditis", "Pulmonary embolism", "Aortic dissection"]'::jsonb, 2, 'Acute myocarditis presents after a viral illness with chest pain, elevated troponin, and diffuse ST elevation mimicking pericarditis or infarction, but with myocardial involvement confirmed by troponin elevation and a normal coronary pattern; the small effusion and positional pain overlap with pericarditis. Acute pericarditis typically has normal troponin or only a trivial rise, whereas this troponin is significantly elevated. Acute myocardial infarction causes regional ST elevation with reciprocal changes and a regional wall motion abnormality, which are absent. Pulmonary embolism causes dyspnea and tachycardia with right heart strain, not diffuse ST elevation. Aortic dissection causes tearing pain radiating to the back with a widened mediastinum.', 'Hard', 53, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 35-year-old woman presents with new-onset heart failure 2 weeks after a flu-like illness. Her ejection fraction is 35% with global hypokinesis. Coronary angiography is normal. The cardiology team orders cardiac MRI to evaluate for myocarditis. Which of the following findings on cardiac MRI is most supportive of the diagnosis of acute myocarditis?', '["Subendocardial late gadolinium enhancement in a coronary territory", "Myocardial edema on T2-weighted imaging with nonischemic late gadolinium enhancement", "Pericardial thickening greater than 4 mm", "Apical ballooning with basal hyperkinesis", "Dilated left ventricle with thin walls"]'::jsonb, 1, 'Cardiac MRI diagnosis of myocarditis uses the Lake Louise criteria: myocardial edema on T2-weighted imaging plus a nonischemic pattern of late gadolinium enhancement (mid-wall or subepicardial), which reflects myocardial inflammation and injury. Subendocardial enhancement in a coronary territory indicates ischemic injury from infarction. Pericardial thickening suggests constrictive pericarditis. Apical ballooning with basal hyperkinesis is characteristic of Takotsubo cardiomyopathy. A dilated thin-walled ventricle suggests chronic dilated cardiomyopathy rather than acute myocarditis, and endomyocardial biopsy is reserved for fulminant or rapidly progressive cases.', 'Hard', 54, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 26-year-old man is diagnosed with acute viral myocarditis with an ejection fraction of 38% and NYHA class II symptoms. He is hemodynamically stable with no arrhythmias. He asks about activity and treatment. Which of the following is the most appropriate management?', '["High-dose corticosteroids", "Immediate implantable cardioverter-defibrillator placement", "Avoid strenuous exercise and start guideline-directed heart failure therapy", "Intravenous immunoglobulin", "Coronary artery bypass grafting"]'::jsonb, 2, 'Management of acute myocarditis with left ventricular dysfunction is supportive: avoid strenuous exercise for 3-6 months to reduce arrhythmia and sudden death risk, and start guideline-directed heart failure therapy (ACE inhibitor/ARNI, beta-blocker) for the reduced ejection fraction. Corticosteroids and immunosuppression are reserved for specific causes such as giant cell myocarditis, sarcoidosis, or eosinophilic myocarditis, not routine viral myocarditis. An ICD is not indicated acutely because the dysfunction may recover and a waiting period is required. Intravenous immunoglobulin has no proven benefit in adult viral myocarditis. Bypass surgery is irrelevant with normal coronaries.', 'Medium', 55, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 60-year-old man with ischemic cardiomyopathy has an ejection fraction of 30% despite 4 months of maximally tolerated sacubitril-valsartan, metoprolol succinate, spironolactone, and dapagliflozin. He remains NYHA class II with no recent hospitalizations. His ECG shows sinus rhythm at 70/min with a narrow QRS of 90 ms. He has no history of sustained ventricular arrhythmia. Which of the following is the most appropriate next step in management?', '["Implantable cardioverter-defibrillator placement", "Cardiac resynchronization therapy", "Add digoxin", "Add ivabradine", "Refer for heart transplantation"]'::jsonb, 0, 'An ICD is indicated for primary prevention of sudden cardiac death in patients with an ejection fraction of 35% or less, NYHA class II-III symptoms, on optimal guideline-directed therapy for at least 3 months, with a life expectancy greater than 1 year. Cardiac resynchronization therapy requires a wide QRS, typically a left bundle branch block of 130 ms or greater, which this patient lacks. Digoxin reduces hospitalizations but does not prevent sudden death. Ivabradine requires a heart rate of 70/min or higher on maximal beta-blocker with persistent symptoms, and this patient''s rate is exactly 70/min on a maximally tolerated dose, making it a weaker option than the mortality-reducing ICD. Transplant is not indicated for a stable NYHA II patient.', 'Hard', 56, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 64-year-old woman with nonischemic cardiomyopathy has an ejection fraction of 30% and NYHA class III symptoms despite 6 months of sacubitril-valsartan, carvedilol, spironolactone, and dapagliflozin. Her ECG shows sinus rhythm with a left bundle branch block and a QRS duration of 165 ms. She has no history of sustained ventricular tachycardia. Which of the following is the most appropriate device therapy?', '["Single-chamber pacemaker", "Implantable cardioverter-defibrillator alone", "Cardiac resynchronization therapy with defibrillator", "Implantable loop recorder", "No device therapy"]'::jsonb, 2, 'Cardiac resynchronization therapy with a defibrillator (CRT-D) is indicated when the ejection fraction is 35% or less, the patient has NYHA class II-IV symptoms despite optimal guideline-directed therapy, and there is a left bundle branch block with a QRS duration of 150 ms or greater; the CRT component corrects ventricular dyssynchrony while the defibrillator provides primary prevention of sudden death. A single-chamber pacemaker does not resynchronize the ventricles. An ICD alone does not correct dyssynchrony and would leave the left bundle branch block untreated. An implantable loop recorder only monitors rhythm. Withholding device therapy would miss a class I indication for both CRT and ICD in this patient.', 'Hard', 57, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 57-year-old man is 3 weeks post-myocardial infarction with an ejection fraction of 30% and NYHA class II symptoms. He is on sacubitril-valsartan, metoprolol, and spironolactone. He asks about an implantable cardioverter-defibrillator for sudden death prevention. Which of the following is the most appropriate response?', '["An ICD should be placed immediately", "An ICD is contraindicated because his ejection fraction is too high", "An ICD is only indicated after a documented cardiac arrest", "ICD placement should be deferred until at least 40 days after the myocardial infarction", "A wearable defibrillator is a permanent alternative to an ICD"]'::jsonb, 3, 'Primary prevention ICD implantation is deferred until at least 40 days after myocardial infarction (and 90 days after revascularization) because early ICDs do not improve survival; the ejection fraction may recover and the risk-benefit balance favors waiting while guideline-directed therapy is optimized. Immediate placement is not recommended for the same reason. An ejection fraction of 30% meets the threshold of 35% or less, so it is not too high. An ICD is indicated for primary prevention in high-risk patients, not only after cardiac arrest. A wearable defibrillator is a temporary bridge, not a permanent alternative to an implanted device.', 'Medium', 58, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 68-year-old man with severe COPD (FEV1 32% predicted) presents with progressive dyspnea, ankle swelling, and abdominal fullness over 2 months. He uses home oxygen and has a chronic cough with sputum. Examination shows jugular venous distension, a loud pulmonic component of the second heart sound, a right ventricular heave, hepatomegaly, and 3+ pitting edema. Echocardiography shows a dilated right ventricle with preserved left ventricular function. Which of the following is the most likely diagnosis?', '["Left-sided heart failure", "Cor pulmonale", "Constrictive pericarditis", "Cardiac tamponade", "Nephrotic syndrome"]'::jsonb, 1, 'Cor pulmonale is right ventricular failure secondary to pulmonary disease, here severe COPD with chronic hypoxia causing pulmonary hypertension; it presents with right-sided congestion (jugular venous distension, hepatomegaly, edema), a loud P2, and a dilated right ventricle with preserved left ventricular function. Left-sided heart failure would show pulmonary congestion and left ventricular dysfunction. Constrictive pericarditis causes a pericardial knock and equalization of pressures, not a dilated right ventricle from lung disease. Tamponade presents acutely with hypotension and pulsus paradoxus. Nephrotic syndrome causes edema from hypoalbuminemia but not jugular venous distension or a loud P2.', 'Medium', 59, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 62-year-old woman with cor pulmonale from severe COPD is admitted with worsening peripheral edema, ascites, and dyspnea. Her oxygen saturation is 88% on 2 L of oxygen, blood pressure 118/72 mmHg, and she has marked jugular venous distension and a tender, enlarged liver. Her creatinine is 1.0 mg/dL and potassium is 4.1 mEq/L. Which of the following is the most appropriate management of her right heart failure?', '["Start intravenous nitroglycerin", "Start high-dose beta-blocker therapy", "Restrict fluids to 500 mL per day and give no diuretics", "Start sacubitril-valsartan", "Optimize oxygenation, treat the underlying lung disease, and give diuretics for volume overload"]'::jsonb, 4, 'Management of cor pulmonale centers on treating the underlying pulmonary disease and correcting hypoxia with supplemental oxygen, which lowers pulmonary vascular resistance, plus diuretics for right-sided volume overload while avoiding over-diuresis that would reduce right ventricular preload. Nitroglycerin lowers preload excessively and can worsen right ventricular output. Beta-blockers are poorly tolerated in cor pulmonale and do not treat the underlying cause. Sacubitril-valsartan is a left heart failure therapy with no established role in cor pulmonale. Severe fluid restriction without diuretics is not effective management of symptomatic right heart failure.', 'Medium', 60, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 76-year-old man with hypertension and type 2 diabetes mellitus presents with 3 days of palpitations and mild dyspnea. His pulse is irregularly irregular at 118 beats/min, blood pressure 138/82 mmHg, and oxygen saturation 97% on room air. ECG shows atrial fibrillation with a rapid ventricular response and no ischemic changes. Echocardiogram shows a normal ejection fraction and a mildly enlarged left atrium. He is hemodynamically stable and has no history of stroke, heart failure, or bleeding. Which of the following is the most appropriate management?', '["Start aspirin alone for stroke prevention and discharge home", "Perform immediate synchronized cardioversion without anticoagulation", "Start a beta-blocker for rate control and apixaban for anticoagulation", "Start amiodarone for rhythm control and defer anticoagulation", "Admit for intravenous heparin and plan cardioversion in 48 hours"]'::jsonb, 2, 'His CHA2DS2-VASc score is 4 (age 75 or older = 2 points, hypertension = 1, diabetes = 1), so anticoagulation is clearly indicated, and a direct oral anticoagulant such as apixaban is preferred over warfarin. He is older and only mildly symptomatic, so rate control is appropriate and non-inferior to rhythm control for such patients. Aspirin alone is inadequate for stroke prevention in atrial fibrillation. Immediate cardioversion without anticoagulation is unsafe because his symptoms have lasted 3 days, beyond the 48-hour window. Amiodarone for rhythm control is not superior here and does not remove the need for anticoagulation. Intravenous heparin with planned cardioversion is unnecessary because he is stable and does not need urgent rhythm restoration.', 'Medium', 61, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 55-year-old man with no significant medical history presents with palpitations that began 30 hours ago. His heart rate is 132 beats/min and irregular, blood pressure 124/78 mmHg, and he is comfortable at rest. ECG confirms atrial fibrillation with a rapid ventricular response. He has no history of hypertension, diabetes, heart failure, or stroke, and he takes no medications. He asks to have his normal rhythm restored today. Which of the following is the most appropriate next step?', '["Begin warfarin and schedule elective cardioversion in 3 weeks", "Perform a transesophageal echocardiogram before any cardioversion", "Start a beta-blocker for rate control and discharge without cardioversion", "Start intravenous heparin and cardiovert after 24 hours of anticoagulation", "Perform synchronized electrical cardioversion now"]'::jsonb, 4, 'Atrial fibrillation of clearly documented duration under 48 hours can be cardioverted without prior anticoagulation or a transesophageal echocardiogram, because the risk of left atrial thrombus is minimal in that window. Delaying cardioversion for 3 weeks of warfarin is unnecessary when onset is known to be under 48 hours. A transesophageal echocardiogram is required when the duration is over 48 hours or unknown, which is not the case here. Rate control alone ignores his reasonable request for rhythm restoration when cardioversion is safe today. A heparin bridge is not needed for cardioversion within 48 hours of onset.', 'Medium', 62, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 68-year-old woman with atrial fibrillation presents with acute dyspnea and chest discomfort. Her heart rate is 168 beats/min and irregular, blood pressure 82/54 mmHg, respiratory rate 28/min, and oxygen saturation 89% on room air. Examination reveals pulmonary crackles and jugular venous distention. ECG shows atrial fibrillation with a rapid ventricular response. Which of the following is the most appropriate immediate management?', '["Intravenous diltiazem for rate control", "Synchronized electrical cardioversion", "Intravenous metoprolol for rate control", "Intravenous digoxin for rate control", "Intravenous amiodarone for rhythm control"]'::jsonb, 1, 'Hypotension, pulmonary edema, and chest pain make this unstable atrial fibrillation, and the definitive immediate treatment is synchronized electrical cardioversion. Atrioventricular nodal blocking agents such as diltiazem, metoprolol, and digoxin act too slowly and can worsen hypotension, so they are inappropriate in an unstable patient. Digoxin is additionally slow in onset and ineffective for acute rate control in this setting. Amiodarone is a rate and rhythm control drug, not the immediate treatment for unstable atrial fibrillation; cardioversion restores perfusion fastest.', 'Easy', 63, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 28-year-old woman presents with sudden-onset palpitations and lightheadedness. Her heart rate is 192 beats/min, blood pressure 118/76 mmHg, and she is alert. ECG shows a regular narrow-complex tachycardia at 190 beats/min with no visible P waves. Vagal maneuvers, including a modified Valsalva, fail to terminate the rhythm. Which of the following is the most appropriate next step?', '["Adenosine 6 mg rapid intravenous push", "Intravenous diltiazem", "Synchronized electrical cardioversion", "Intravenous metoprolol", "Oral flecainide"]'::jsonb, 0, 'This is stable regular narrow-complex supraventricular tachycardia, most likely AVNRT, after failed vagal maneuvers. Adenosine 6 mg as a rapid intravenous push followed by a saline flush, repeated at 12 mg if needed, is the first-line drug to terminate it by transiently blocking the atrioventricular node; its half-life is under 10 seconds, so rapid administration is essential. Diltiazem and metoprolol act over minutes and are second-line for acute termination. Synchronized cardioversion is reserved for unstable supraventricular tachycardia, and she is hemodynamically stable. Oral flecainide is not first-line for acute termination of AVNRT.', 'Medium', 64, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 45-year-old man presents with palpitations and confusion. His heart rate is 210 beats/min, blood pressure 76/48 mmHg, and he is diaphoretic and lethargic. ECG shows a regular narrow-complex tachycardia. Intravenous access is being obtained. Which of the following is the most appropriate immediate management?', '["Vagal maneuvers", "Adenosine 6 mg intravenous push", "Intravenous verapamil", "Synchronized electrical cardioversion", "Intravenous amiodarone"]'::jsonb, 3, 'Hypotension with altered mental status makes this unstable supraventricular tachycardia, and the immediate treatment is synchronized electrical cardioversion, with sedation if time permits; do not delay it to try drugs or vagal maneuvers. Adenosine should not be tried first in an unstable patient because its effect is transient and it wastes critical time while perfusion remains inadequate. Verapamil can worsen hypotension and is contraindicated in this setting. Amiodarone is not first-line therapy for unstable supraventricular tachycardia and acts too slowly to restore perfusion promptly.', 'Easy', 65, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 34-year-old woman has had three episodes of sudden-onset palpitations in the past 2 months, each lasting 20 to 40 minutes and resolving spontaneously. During an episode, her heart rate is 185 beats/min with a regular narrow-complex tachycardia consistent with AVNRT. She is otherwise healthy and asks for a treatment that will prevent future episodes permanently. Which of the following is the most appropriate management?', '["Daily oral beta-blocker", "Daily oral verapamil", "Radiofrequency catheter ablation of the slow pathway", "Adenosine to use as needed during episodes", "Implantable loop recorder"]'::jsonb, 2, 'Recurrent symptomatic AVNRT is best treated definitively with radiofrequency catheter ablation of the slow atrioventricular nodal pathway, which is curative in over 95% of cases with a low complication rate and is exactly the permanent solution this patient is asking for. Daily beta-blockers or verapamil only suppress episodes, require lifelong adherence, and do not cure the arrhythmia. Adenosine treats acute episodes but does nothing to prevent them. An implantable loop recorder is a diagnostic tool, not a treatment, and the diagnosis here is already established.', 'Medium', 66, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 64-year-old man with a prior myocardial infarction and heart failure with an ejection fraction of 30% presents with palpitations and dyspnea. His heart rate is 172 beats/min, blood pressure 116/74 mmHg, and he is alert. ECG shows a regular wide-complex tachycardia with a monomorphic pattern. Which of the following is the most appropriate initial treatment?', '["Intravenous adenosine", "Intravenous amiodarone", "Synchronized electrical cardioversion", "Intravenous lidocaine", "Intravenous procainamide"]'::jsonb, 1, 'This is stable monomorphic ventricular tachycardia in a patient with severe left ventricular dysfunction, and intravenous amiodarone 150 mg over 10 minutes is the preferred initial drug because it is safest in heart failure with reduced ejection fraction. Adenosine is used for supraventricular tachycardia with aberrancy, not ventricular tachycardia. Synchronized cardioversion is reserved for unstable ventricular tachycardia, and he is hemodynamically stable. Lidocaine is less effective and second-line. Procainamide is an acceptable alternative but can cause hypotension and is less favored with severe left ventricular dysfunction.', 'Hard', 67, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 58-year-old woman presents with chest pain and severe dyspnea. Her heart rate is 184 beats/min, blood pressure 78/50 mmHg, and she has pulmonary edema. ECG shows a regular wide-complex tachycardia consistent with monomorphic ventricular tachycardia. Which of the following is the most appropriate immediate management?', '["Intravenous amiodarone", "Intravenous procainamide", "Intravenous lidocaine", "Unsynchronized defibrillation", "Synchronized electrical cardioversion"]'::jsonb, 4, 'Hypotension with pulmonary edema makes this unstable ventricular tachycardia with a pulse, and the immediate treatment is synchronized electrical cardioversion, which times the shock to the R wave to avoid the vulnerable period. Intravenous amiodarone, procainamide, and lidocaine all delay definitive therapy in an unstable patient and act too slowly to restore perfusion. Unsynchronized defibrillation is used for pulseless ventricular tachycardia or ventricular fibrillation, not for ventricular tachycardia with a pulse. After cardioversion, the underlying cause should be evaluated and secondary prevention addressed.', 'Medium', 68, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 60-year-old man is resuscitated from an out-of-hospital ventricular fibrillation arrest. Coronary angiography shows no obstructive coronary disease, electrolytes are normal, and echocardiogram shows an ejection fraction of 40%. No reversible cause for the arrest is identified. He has recovered fully and is hemodynamically stable. Which of the following is the most appropriate next step to prevent sudden cardiac death?', '["Implantation of an implantable cardioverter-defibrillator", "Oral amiodarone alone", "Oral beta-blocker alone", "No further therapy, with close follow-up", "Wearable cardioverter-defibrillator as permanent therapy"]'::jsonb, 0, 'A survivor of ventricular fibrillation arrest without a reversible cause has a Class I indication for an implantable cardioverter-defibrillator for secondary prevention; trials such as AVID showed the ICD superior to amiodarone for survival. Amiodarone reduces arrhythmia recurrence but does not lower mortality to the same degree and is not a substitute for the device. A beta-blocker alone is an adjunct, not definitive protection. No further therapy leaves him at high risk of recurrent arrest. A wearable defibrillator is only a temporary bridge, for example while awaiting device implantation, not definitive long-term protection.', 'Medium', 69, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 58-year-old man is admitted with an inferior ST-elevation myocardial infarction. On day 2, his heart rate is 62 beats/min and he is asymptomatic with a blood pressure of 122/78 mmHg. ECG shows second-degree atrioventricular block, Mobitz type I (Wenckebach), with progressive PR prolongation before a dropped beat. Which of the following is the most appropriate management?', '["Permanent pacemaker implantation", "Transcutaneous pacing", "Intravenous atropine", "Observation with continuous cardiac monitoring", "Intravenous isoproterenol infusion"]'::jsonb, 3, 'Asymptomatic Mobitz type I block is at the atrioventricular node, is often vagally mediated after an inferior infarction, and is usually transient and benign, so observation with continuous monitoring is appropriate. A permanent pacemaker is not indicated for asymptomatic Mobitz type I block, since pacing is reserved for symptomatic or high-risk conduction disease. Transcutaneous pacing is unnecessary without symptoms or hemodynamic compromise. Atropine and isoproterenol are used only for symptomatic bradycardia and have no role in a stable, asymptomatic patient.', 'Easy', 70, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 70-year-old woman is found to have second-degree atrioventricular block, Mobitz type II, on a routine ECG. Her heart rate is 58 beats/min, blood pressure 128/80 mmHg, and she reports no symptoms. Echocardiogram shows a normal ejection fraction. Which of the following is the most appropriate management?', '["Observation with annual ECG monitoring", "Oral atropine as needed", "Permanent pacemaker implantation", "Temporary transvenous pacing", "Start a beta-blocker to control the rate"]'::jsonb, 2, 'Mobitz type II block is infranodal, often with a wide QRS, and carries a high risk of progressing to complete heart block and sudden death, so a permanent pacemaker is indicated even in asymptomatic patients. Observation is unsafe given the risk of sudden progression to complete block. Atropine acts at the atrioventricular node and is usually ineffective for infranodal His-Purkinje disease, and it is not available as an oral drug. Temporary transvenous pacing is not needed because she is stable, and it does not address the long-term risk. A beta-blocker would worsen atrioventricular conduction.', 'Hard', 71, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 74-year-old man presents after a syncopal episode. His heart rate is 38 beats/min, blood pressure 86/60 mmHg, and he is confused and cool to the touch. ECG shows complete (third-degree) atrioventricular block with atrioventricular dissociation. Atropine 1 mg intravenously has been given without improvement in heart rate or blood pressure. Which of the following is the most appropriate next step?', '["Repeat atropine 1 mg intravenously", "Transcutaneous pacing", "Intravenous dopamine infusion", "Immediate permanent pacemaker implantation", "Intravenous isoproterenol infusion"]'::jsonb, 1, 'Symptomatic complete heart block unresponsive to atropine, which is typical for infranodal block, requires transcutaneous pacing as the immediate step in the ACLS symptomatic bradycardia algorithm, with sedation and analgesia as tolerated. Repeating atropine is unlikely to work when the first dose failed, since atropine acts at the atrioventricular node rather than the His-Purkinje system. Dopamine and isoproterenol infusions are adjuncts if pacing fails or is unavailable, not the first step. A permanent pacemaker will be needed later, but immediate stabilization with transcutaneous pacing comes first.', 'Medium', 72, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 54-year-old woman on methadone maintenance therapy presents with recurrent syncope. Her serum magnesium is 1.4 mg/dL and potassium 3.6 mEq/L. ECG shows a QTc of 540 ms and episodes of polymorphic ventricular tachycardia with twisting QRS complexes around the baseline. Her blood pressure is 118/72 mmHg and she is currently alert. Which of the following is the most appropriate immediate treatment?', '["Intravenous magnesium sulfate", "Intravenous amiodarone", "Intravenous calcium gluconate", "Intravenous procainamide", "Synchronized electrical cardioversion"]'::jsonb, 0, 'This is torsades de pointes from acquired QT prolongation due to methadone plus hypomagnesemia, and intravenous magnesium sulfate 2 g over 10 to 15 minutes is the treatment of choice because it suppresses early afterdepolarizations, even when magnesium is normal; the methadone should also be stopped and potassium repleted to 4.5 to 5.0 mEq/L. Amiodarone and procainamide both prolong the QT interval and would worsen torsades. Calcium gluconate is used for hyperkalemia, not torsades. Cardioversion is reserved for unstable or pulseless torsades, and she is currently stable with a perfusing rhythm.', 'Medium', 73, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 22-year-old woman with congenital long QT syndrome has had two syncopal episodes in the past year despite taking nadolol, a long-acting beta-blocker. One episode occurred while swimming. Her QTc is 520 ms, echocardiogram is normal, and she has no other medical problems. Which of the following is the most appropriate next step?', '["Increase the nadolol dose and add a calcium channel blocker", "Discontinue the beta-blocker and start flecainide", "Reassurance and avoidance of strenuous exercise only", "Left cardiac sympathetic denervation alone", "Implantation of an implantable cardioverter-defibrillator"]'::jsonb, 4, 'Congenital long QT syndrome with syncope despite beta-blocker therapy marks her as high risk for sudden cardiac death, and an implantable cardioverter-defibrillator is indicated. Increasing the beta-blocker dose is insufficient after it has already failed, and a calcium channel blocker has no role. Stopping the beta-blocker removes her only protection, and flecainide is not indicated for long QT syndrome. Reassurance alone is unsafe after recurrent syncope. Left cardiac sympathetic denervation is an adjunct, not a substitute for an ICD in this high-risk patient.', 'Hard', 74, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 68-year-old woman with schizophrenia is brought to the emergency department after a syncopal episode. She takes haloperidol and was recently started on erythromycin for pneumonia. Her potassium is 3.1 mEq/L, magnesium 1.5 mg/dL, and ECG shows a QTc of 560 ms with frequent premature ventricular complexes. Which of the following is the most appropriate immediate management?', '["Start intravenous amiodarone", "Start oral sotalol", "Discontinue haloperidol and erythromycin and replete potassium and magnesium", "Administer intravenous calcium gluconate", "Start a beta-blocker"]'::jsonb, 2, 'This is acquired long QT syndrome from two QT-prolonging drugs that block cardiac potassium channels, combined with hypokalemia and hypomagnesemia that amplify the risk. The cornerstone of management is removing the triggers by stopping haloperidol and erythromycin and repleting potassium to 4.5 to 5.0 mEq/L and magnesium, with continuous monitoring for torsades. Amiodarone and sotalol both prolong the QT interval and would increase the risk of torsades. Calcium gluconate does not address QT prolongation. A beta-blocker alone does not correct the underlying cause acutely, although beta-blockers are mainstays for congenital long QT syndrome.', 'Medium', 75, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 32-year-old man with known Wolff-Parkinson-White syndrome presents with palpitations and dyspnea. His heart rate is 196 beats/min, blood pressure 122/78 mmHg. ECG shows an irregular wide-complex tachycardia with varying QRS morphology, consistent with atrial fibrillation with rapid conduction down an accessory pathway. Which of the following is the most appropriate treatment?', '["Intravenous adenosine", "Intravenous diltiazem", "Intravenous digoxin", "Intravenous procainamide", "Synchronized electrical cardioversion"]'::jsonb, 3, 'This is pre-excited atrial fibrillation, in which impulses conduct rapidly down the accessory pathway. Intravenous procainamide blocks the accessory pathway and prolongs its refractory period, making it the drug of choice in a stable patient; ibutilide is an alternative. Atrioventricular nodal blockers including adenosine, diltiazem, and digoxin are contraindicated because blocking the atrioventricular node removes its filtering effect and accelerates conduction down the accessory pathway, risking ventricular fibrillation. Synchronized cardioversion is reserved for unstable patients, and he is hemodynamically stable; after stabilization he should be referred for ablation.', 'Hard', 76, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 24-year-old man is found to have a short PR interval and a delta wave on a routine ECG. He has never had palpitations, syncope, or chest pain, and his examination and echocardiogram are normal. Which of the following is the most appropriate next step?', '["Immediate radiofrequency catheter ablation", "Risk stratification with electrophysiology study or noninvasive testing", "Start a daily beta-blocker", "Start oral flecainide", "Reassurance with no further evaluation"]'::jsonb, 1, 'Asymptomatic Wolff-Parkinson-White pattern requires risk stratification to identify high-risk accessory pathways, such as those with a short refractory period or multiple pathways, which warrant ablation; most asymptomatic patients need neither ablation nor drugs. Stratification is done by electrophysiology study or noninvasively, for example an exercise test showing abrupt loss of pre-excitation, which suggests a low-risk pathway. Immediate ablation without stratification is not indicated. A daily beta-blocker or flecainide is not indicated in an asymptomatic patient. Reassurance with no evaluation at all misses the small but real risk of sudden death from rapid pre-excited atrial fibrillation.', 'Medium', 77, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 35-year-old woman with known Wolff-Parkinson-White syndrome presents with sudden palpitations. Her heart rate is 182 beats/min, blood pressure 116/74 mmHg. ECG shows a regular narrow-complex tachycardia with no visible P waves, consistent with orthodromic atrioventricular reentrant tachycardia. Vagal maneuvers fail. Which of the following is the most appropriate next step?', '["Adenosine 6 mg rapid intravenous push", "Intravenous procainamide", "Synchronized electrical cardioversion", "Intravenous diltiazem", "Intravenous digoxin"]'::jsonb, 0, 'Orthodromic atrioventricular reentrant tachycardia conducts anterogradely through the atrioventricular node and retrogradely through the accessory pathway, so blocking the node with adenosine is safe and first-line therapy. The danger of atrioventricular nodal blockers in Wolff-Parkinson-White syndrome applies to pre-excited atrial fibrillation, an irregular wide-complex rhythm, not to orthodromic reentry. Procainamide is reserved for pre-excited atrial fibrillation. Cardioversion is for unstable patients, and she is stable. Diltiazem is second-line for acute termination, and digoxin should be avoided in Wolff-Parkinson-White syndrome because it can shorten the accessory pathway refractory period.', 'Medium', 78, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 19-year-old woman faints after standing in a hot shower for 20 minutes. She recalls nausea, sweating, and tunnel vision before losing consciousness briefly, then recovered quickly and completely. Examination and ECG are normal, and she has had two similar episodes in the past year, both while standing in warm environments. Which of the following is the most appropriate management?', '["Admit for continuous telemetry monitoring", "Tilt-table testing", "Reassurance, hydration, and avoidance of triggers", "Implantable loop recorder", "Start fludrocortisone"]'::jsonb, 2, 'This is classic vasovagal syncope: a clear prodrome, a typical trigger of prolonged standing in heat, brief loss of consciousness with rapid complete recovery, and a normal examination and ECG. It is benign, and management is reassurance, adequate hydration and salt intake, trigger avoidance, and physical counterpressure maneuvers. Admission for telemetry is unnecessary. Tilt-table testing and an implantable loop recorder are not needed when the presentation is classic and the evaluation is normal. Fludrocortisone is reserved for refractory orthostatic hypotension, not first-line vasovagal syncope.', 'Easy', 79, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 68-year-old man presents after fainting while climbing stairs. He reports exertional dyspnea and chest tightness over the past month. Examination reveals a harsh crescendo-decrescendo systolic murmur loudest at the right second intercostal space radiating to the carotids, with a delayed carotid upstroke. ECG shows left ventricular hypertrophy. Which of the following is the most appropriate next step?', '["Tilt-table testing", "Computed tomography of the head", "Carotid Doppler ultrasonography", "Reassurance and outpatient follow-up in 6 months", "Transthoracic echocardiography with cardiology referral"]'::jsonb, 4, 'Exertional syncope with a harsh systolic murmur radiating to the carotids and a delayed upstroke indicates severe aortic stenosis, a cardiac cause of syncope with high risk of sudden death. Transthoracic echocardiography to confirm severity with urgent cardiology referral is the next step, and these patients are admitted for evaluation toward valve replacement. Tilt-table testing is for vasovagal or orthostatic syncope, not exertional cardiac syncope. Head CT is indicated for neurologic signs, which are absent. Carotid Doppler does not evaluate the valve. Reassurance is dangerous in exertional syncope.', 'Medium', 80, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'An 82-year-old woman presents after fainting when she stood up from bed. She takes lisinopril, amlodipine, and metoprolol for hypertension. Supine blood pressure is 142/84 mmHg and falls to 98/60 mmHg on standing, with a heart rate rise of only 4 beats/min. ECG is normal and echocardiogram shows a normal ejection fraction. Which of the following is the most appropriate initial management?', '["Permanent pacemaker implantation", "Implantable cardioverter-defibrillator", "Referral for electrophysiology study", "Review and adjust antihypertensive medications, with volume repletion", "Start midodrine immediately"]'::jsonb, 3, 'This is orthostatic hypotension caused by antihypertensive medications, with a blunted heart rate response from metoprolol; orthostatic hypotension is defined as a fall in systolic pressure of at least 20 mmHg or diastolic pressure of at least 10 mmHg within 3 minutes of standing. The first step is medication review and reduction, adequate hydration, and slow position changes, plus non-drug measures such as compression stockings. There is no conduction disease to pace and no ventricular arrhythmia risk to justify a defibrillator, and an electrophysiology study is not indicated. Midodrine is second-line therapy, used only after medication adjustment and conservative measures have failed.', 'Medium', 81, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 62-year-old man had a myocardial infarction 6 months ago and has heart failure with an ejection fraction of 28% despite 4 months of guideline-directed medical therapy including a beta-blocker, ACE inhibitor, and mineralocorticoid receptor antagonist. He has NYHA class II symptoms, a QRS duration of 110 ms, and no prior ventricular arrhythmias. Which of the following is the most appropriate next step?', '["Continue medical therapy alone and repeat echocardiogram in 6 months", "Implantation of an implantable cardioverter-defibrillator", "Cardiac resynchronization therapy with defibrillator (CRT-D)", "Oral amiodarone", "Electrophysiology study to assess inducibility"]'::jsonb, 1, 'An ejection fraction of 35% or less with NYHA class II symptoms on guideline-directed therapy for at least 3 months and more than 40 days after myocardial infarction is a Class I indication for an ICD for primary prevention of sudden cardiac death. Cardiac resynchronization therapy requires a wide QRS, typically left bundle branch block of 150 ms or more, and his QRS is 110 ms. Amiodarone does not reduce mortality the way an ICD does. An electrophysiology study is not required before primary prevention ICD implantation, and delaying with another echocardiogram leaves him unprotected.', 'Hard', 82, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 71-year-old man reports progressive fatigue and lightheadedness over 2 months. His heart rate is 38 beats/min, blood pressure 104/66 mmHg. ECG shows sinus bradycardia at 38 beats/min with no atrioventricular block. He takes no rate-slowing medications, thyroid studies are normal, and there is no evidence of ischemia or electrolyte abnormality. Which of the following is the most appropriate management?', '["Permanent pacemaker implantation", "Intravenous atropine as needed", "Oral theophylline", "Reassurance and observation", "Temporary transvenous pacing"]'::jsonb, 0, 'Symptomatic sinus bradycardia with no reversible cause is a Class I indication for a permanent pacemaker, after ruling out rate-slowing drugs, hypothyroidism, ischemia, electrolyte abnormalities, and sleep apnea, all of which are absent here. Atropine provides only temporary relief and is not a long-term solution. Theophylline is not standard therapy for symptomatic sinus node dysfunction. Reassurance is inappropriate when bradycardia is causing fatigue and lightheadedness. Temporary transvenous pacing is a bridge for acute instability, not definitive therapy for chronic symptomatic bradycardia.', 'Easy', 83, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 66-year-old man with an implantable cardioverter-defibrillator placed after a myocardial infarction reports two painful shocks while awake today. He is now in atrial fibrillation with a heart rate of 152 beats/min, blood pressure 118/76 mmHg. Device interrogation shows both shocks were delivered for rapidly conducted atrial fibrillation, with no ventricular tachycardia or fibrillation. Which of the following is the most appropriate next step?', '["Replace the ICD generator", "Start amiodarone for rhythm control", "Interrogate the device and initiate rate control for atrial fibrillation", "Disable ICD therapies", "Reassure the patient that the shocks were appropriate"]'::jsonb, 2, 'These were inappropriate shocks delivered for rapidly conducted atrial fibrillation, so the correct response is to treat the cause with rate control using a beta-blocker or calcium channel blocker and to reprogram the device with adjusted detection zones and supraventricular tachycardia discriminators. Generator replacement is unnecessary because the device functioned as programmed. Amiodarone is not first-line for rate control here. Disabling therapies would leave him unprotected from true ventricular arrhythmias. The shocks were inappropriate, not appropriate, and require evaluation rather than reassurance.', 'Medium', 84, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 70-year-old man presents with palpitations and mild dyspnea. His heart rate is 150 beats/min and regular, blood pressure 130/80 mmHg, oxygen saturation 96% on room air. ECG shows sawtooth flutter waves with 2:1 atrioventricular conduction. He has no chest pain and no pulmonary edema. Which of the following is the most appropriate management?', '["Synchronized electrical cardioversion", "Intravenous adenosine", "Oral digoxin alone", "Intravenous amiodarone for rhythm control", "Rate control with diltiazem and initiation of anticoagulation"]'::jsonb, 4, 'Stable typical atrial flutter with 2:1 conduction at 150 beats/min is managed with rate control using diltiazem or a beta-blocker plus anticoagulation, since flutter carries the same stroke risk as atrial fibrillation and the CHA2DS2-VASc score applies. Cardioversion is reserved for unstable patients or for elective rhythm control after anticoagulation or a transesophageal echocardiogram. Adenosine does not terminate flutter, though it may transiently unmask the flutter waves. Digoxin alone is slow and poor for rate control in flutter. Amiodarone is not the first step in a stable patient.', 'Medium', 85, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 64-year-old woman with known atrial flutter presents with severe dyspnea and chest discomfort. Her heart rate is 162 beats/min, blood pressure 84/56 mmHg, and examination reveals pulmonary edema. ECG confirms atrial flutter with 2:1 conduction. Which of the following is the most appropriate immediate management?', '["Intravenous diltiazem", "Intravenous metoprolol", "Intravenous digoxin", "Synchronized electrical cardioversion", "Intravenous amiodarone"]'::jsonb, 3, 'Hypotension with pulmonary edema makes this unstable atrial flutter, and the immediate treatment is synchronized electrical cardioversion, with sedation if time permits; the shock is timed to the R wave to avoid the vulnerable period of the cardiac cycle. Rate-control drugs such as diltiazem, metoprolol, and digoxin can worsen hypotension and act too slowly in an unstable patient, so they must not be tried first. Amiodarone is not the immediate treatment for an unstable tachyarrhythmia; restoring sinus rhythm by cardioversion restores perfusion fastest. After cardioversion, anticoagulation should be continued based on the CHA2DS2-VASc score.', 'Medium', 86, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 60-year-old man has had three episodes of symptomatic typical atrial flutter in the past 6 months, each requiring cardioversion. He is currently in sinus rhythm on a beta-blocker but continues to have palpitations and fatigue with recurrences. He asks for a treatment that will stop the episodes permanently. Which of the following is the most appropriate management?', '["Lifelong oral amiodarone", "Catheter ablation of the cavotricuspid isthmus", "Repeat electrical cardioversion as needed", "Continue the beta-blocker and accept recurrences", "Left atrial appendage occlusion"]'::jsonb, 1, 'Recurrent symptomatic typical atrial flutter is best treated definitively with catheter ablation of the cavotricuspid isthmus, which is curative in over 95% of cases with a low complication rate and is first-line definitive therapy. Lifelong amiodarone carries significant toxicity affecting the thyroid, lungs, liver, and eyes and is not curative. Repeated cardioversion treats each episode but does not prevent recurrence. Continuing a beta-blocker that has already failed does not address his goal. Left atrial appendage occlusion is a stroke-prevention strategy for atrial fibrillation, not a treatment for flutter; anticoagulation decisions after ablation still follow the CHA2DS2-VASc score.', 'Hard', 87, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 45-year-old woman reports occasional palpitations but is otherwise well. Holter monitoring shows frequent premature ventricular complexes comprising 8% of beats, with no runs of ventricular tachycardia. Echocardiogram shows a normal ejection fraction and no structural heart disease, and she has no syncope or dyspnea. Which of the following is the most appropriate management?', '["Reassurance and avoidance of stimulants such as caffeine", "Start oral amiodarone", "Start a beta-blocker", "Catheter ablation", "Implantable cardioverter-defibrillator"]'::jsonb, 0, 'Minimally symptomatic premature ventricular complexes with a structurally normal heart and preserved ejection fraction are benign and require only reassurance and avoidance of triggers such as caffeine, alcohol, and other stimulants. Amiodarone toxicity is not justified for benign ectopy. Beta-blockers are used when premature beats are symptomatic, which she is not. Catheter ablation is reserved for symptomatic or refractory cases or premature ventricular complex-induced cardiomyopathy. An ICD is indicated for high sudden-death risk, such as an ejection fraction of 35% or less with other indications, not benign premature beats.', 'Easy', 88, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 58-year-old man has an ejection fraction of 35% with no obstructive coronary disease on angiography and no other identifiable cause of cardiomyopathy. Holter monitoring shows premature ventricular complexes comprising 22% of all beats. He reports mild exertional dyspnea but no syncope. Which of the following is the most appropriate initial management?', '["Implant an ICD now for primary prevention", "Start amiodarone to suppress the PVCs", "Start a beta-blocker and repeat echocardiogram in 3 months", "Proceed directly to catheter ablation", "Reassurance only"]'::jsonb, 2, 'A high premature ventricular complex burden with a reduced ejection fraction and no other cause indicates premature ventricular complex-induced cardiomyopathy, a reversible cause of left ventricular dysfunction. First-line management is a beta-blocker, which also treats heart failure, with a repeat echocardiogram in 3 months to assess recovery; catheter ablation is considered if the burden and ejection fraction do not improve. An ICD is not indicated before treating the reversible cause. Amiodarone is not first-line here. Reassurance alone ignores a treatable cause of cardiomyopathy.', 'Hard', 89, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 52-year-old woman has daily palpitations from frequent premature ventricular complexes that limit her work and exercise. Echocardiogram is normal with an ejection fraction of 60%. A beta-blocker and a calcium channel blocker have both failed to relieve her symptoms. Which of the following is the most appropriate next step?', '["Start oral amiodarone", "Reassurance and acceptance of symptoms", "Implantable cardioverter-defibrillator", "Oral flecainide", "Catheter ablation of the PVC focus"]'::jsonb, 4, 'Symptomatic premature ventricular complexes that are refractory to medical therapy in a structurally normal heart are an indication for catheter ablation, which is definitive and guideline-supported, with success rates of 70 to 90% for focal ectopy. Amiodarone has significant long-term toxicity affecting the lungs, thyroid, and liver and is not preferred for benign premature beats. Reassurance is inadequate when symptoms limit daily life and drugs have already failed. An ICD has no role without high sudden-death risk. Flecainide can suppress premature beats but carries proarrhythmic risk and is not definitive.', 'Medium', 90, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 68-year-old man with a history of hypertension presents with two episodes of exertional syncope over the past month and progressive exertional dyspnea. His blood pressure is 128/82 mmHg and pulse is 78/min. Examination reveals a harsh crescendo-decrescendo systolic murmur loudest at the right upper sternal border radiating to the carotids, with a delayed, diminished carotid upstroke. He is otherwise active with no significant comorbidities and is considered low surgical risk. Transthoracic echocardiography shows an aortic valve area of 0.8 cm2, mean transvalvular gradient of 46 mmHg, and left ventricular ejection fraction of 60%. Which of the following is the most appropriate next step in management?', '["Repeat echocardiography in 12 months and reassess symptoms", "Percutaneous balloon aortic valvuloplasty", "Surgical aortic valve replacement", "Transcatheter aortic valve replacement", "Start a loop diuretic and a beta-blocker"]'::jsonb, 2, 'This is symptomatic severe aortic stenosis (valve area 0.8 cm2, mean gradient 46 mmHg) with syncope and dyspnea, which carries a high mortality without valve replacement. Surgical aortic valve replacement is preferred in a 68-year-old low surgical risk patient, since transcatheter replacement is generally favored in older or high-risk patients and shared decision-making applies at age 65-80. Watchful waiting is wrong in symptomatic severe stenosis. Balloon valvuloplasty is only a bridge in unstable patients, not definitive therapy. Diuretics and beta-blockers do not relieve the fixed obstruction and do not change the prognosis.', 'Medium', 91, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 74-year-old woman is found to have a systolic murmur during a routine visit. She reports no chest pain, dyspnea, or syncope and walks 2 miles daily without symptoms. Examination reveals a harsh crescendo-decrescendo systolic murmur at the right upper sternal border. Transthoracic echocardiography shows an aortic valve area of 0.9 cm2, mean gradient of 48 mmHg, and left ventricular ejection fraction of 58%. An exercise stress test is normal with no symptoms, ST changes, or hypotension. Which of the following is the most appropriate management?', '["Clinical surveillance with repeat echocardiography in 6-12 months", "Surgical aortic valve replacement now", "Transcatheter aortic valve replacement now", "Start high-dose statin therapy to slow valve calcification", "Restrict physical activity and start a beta-blocker"]'::jsonb, 0, 'This is asymptomatic severe aortic stenosis with preserved ejection fraction and a normal exercise test. Valve replacement is indicated only when symptoms develop, ejection fraction falls below 50%, the exercise test is abnormal, or stenosis is very severe. Until then, clinical surveillance with echocardiography every 6-12 months is correct. Surgical or transcatheter replacement now would expose her to procedural risk without benefit. Statins do not slow aortic stenosis progression. Activity restriction and beta-blockers are not indicated in an asymptomatic patient with normal functional capacity.', 'Medium', 92, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'An 82-year-old woman with a history of heart failure presents with progressive exertional dyspnea and fatigue. Echocardiography shows an aortic valve area of 0.8 cm2, mean transvalvular gradient of 28 mmHg, left ventricular ejection fraction of 32%, and a low stroke volume index. She is clinically euvolemic on optimal heart failure therapy. Which of the following is the most appropriate next step to determine whether she has true severe aortic stenosis?', '["Proceed directly to transcatheter aortic valve replacement", "Repeat echocardiography in 6 months", "Cardiac catheterization with left ventriculography", "Dobutamine stress echocardiography", "Start an ACE inhibitor and re-evaluate in 3 months"]'::jsonb, 3, 'This is low-flow, low-gradient aortic stenosis with reduced ejection fraction: the valve area is small but the gradient is low because stroke volume is reduced. Dobutamine stress echocardiography distinguishes true severe stenosis, where the valve area stays 1.0 cm2 or less while the gradient rises, from pseudo-severe stenosis, where the valve area increases as flow improves. Proceeding to valve replacement without confirming severity risks replacing a non-severe valve. Repeat echocardiography will not resolve the ambiguity. Cardiac catheterization does not assess flow reserve, and an ACE inhibitor treats heart failure but is not diagnostic.', 'Hard', 93, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 64-year-old man is admitted with an acute inferior ST-elevation myocardial infarction and undergoes percutaneous coronary intervention. On hospital day 3, he develops acute dyspnea, hypoxemia, and hypotension. Examination reveals a new loud holosystolic murmur at the apex radiating to the axilla, bilateral pulmonary crackles, and an S3 gallop. Echocardiography shows a flail posterior mitral leaflet with severe mitral regurgitation and a left ventricular ejection fraction of 45%. Which of the following is the most appropriate next step in management?', '["Intravenous thrombolytic therapy", "Emergent surgical mitral valve repair or replacement", "Intra-aortic balloon pump alone without surgery", "High-dose loop diuretics and observation", "Urgent coronary artery bypass grafting alone"]'::jsonb, 1, 'Acute severe mitral regurgitation from papillary muscle rupture after myocardial infarction causes cardiogenic shock and pulmonary edema, and the definitive treatment is emergent mitral valve surgery. An intra-aortic balloon pump and afterload reduction are only bridges to surgery, not definitive therapy. Thrombolytics do not correct a mechanical complication and carry bleeding risk after intervention. Diuretics alone cannot fix acute severe regurgitation. Bypass surgery alone does not address the flail leaflet and ruptured papillary muscle. Afterload reduction with nitroprusside and an intra-aortic balloon pump can stabilize the patient as a bridge, but they do not replace emergent surgery, which is the only definitive treatment for this mechanical complication.', 'Hard', 94, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 44-year-old woman who immigrated from South Asia presents with progressive exertional dyspnea, orthopnea, and occasional hemoptysis. She recalls frequent sore throats and joint pains as a child. Examination shows a low-pitched diastolic rumbling murmur at the apex, an opening snap, and a loud first heart sound. Her rhythm is irregularly irregular. Chest radiography shows left atrial enlargement without pulmonary edema. Which of the following is the best initial test to evaluate her valve disease?', '["Cardiac catheterization", "Transesophageal echocardiography", "Chest CT angiography", "Serum B-type natriuretic peptide level", "Transthoracic echocardiography"]'::jsonb, 4, 'A history of rheumatic fever with an opening snap, diastolic rumble, and atrial fibrillation points to mitral stenosis. Transthoracic echocardiography is the best initial test: it confirms the diagnosis, measures valve area and gradient, and assesses left atrial size and pulmonary pressures. Transesophageal echocardiography is used later, before balloon commissurotomy, to exclude left atrial thrombus. Cardiac catheterization is invasive and not the initial test. Chest CT does not assess valve hemodynamics, and natriuretic peptide is nonspecific. Echocardiography also guides further management by measuring the mitral valve area and mean gradient, detecting pulmonary hypertension, and identifying left atrial thrombus risk before any intervention such as balloon commissurotomy.', 'Medium', 95, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 57-year-old man with known mitral valve prolapse presents with progressive exertional dyspnea and fatigue over 6 months. Echocardiography shows severe primary mitral regurgitation due to a flail posterior leaflet, left ventricular ejection fraction of 55%, and left ventricular end-systolic diameter of 42 mm. He has no significant comorbidities. Which of the following is the most appropriate treatment?', '["Medical therapy with an ACE inhibitor and diuretic alone", "Transcatheter mitral valve edge-to-edge repair (MitraClip)", "Surgical mitral valve repair", "Surgical mitral valve replacement with a mechanical prosthesis", "Cardiac resynchronization therapy"]'::jsonb, 2, 'Symptomatic severe primary mitral regurgitation with ejection fraction above 30% is an indication for surgery, and repair is preferred over replacement when feasible because it preserves left ventricular function and improves survival. Medical therapy alone is inadequate for symptomatic severe primary regurgitation. Transcatheter edge-to-edge repair is reserved for patients at high surgical risk or with secondary regurgitation, not a low-risk patient with a flail leaflet. Replacement is second choice when repair is not feasible. Cardiac resynchronization therapy is for heart failure with a wide QRS, not for mitral regurgitation.', 'Medium', 96, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 58-year-old man presents with sudden-onset severe dyspnea and chest discomfort. He is hypotensive at 88/50 mmHg with a heart rate of 118/min. Examination reveals a soft diastolic decrescendo murmur at the left sternal border, elevated jugular venous pressure, and bilateral pulmonary crackles. Echocardiography shows severe aortic regurgitation with premature closure of the mitral valve and a left ventricular ejection fraction of 50%. Blood cultures are pending. Which of the following is the most appropriate next step in management?', '["Intra-aortic balloon pump placement", "Emergent surgical aortic valve replacement", "Intravenous nitroprusside and diuretics alone", "Transcatheter aortic valve replacement", "Intravenous beta-blocker to reduce heart rate"]'::jsonb, 1, 'Acute severe aortic regurgitation causes cardiogenic shock because the unprepared left ventricle cannot tolerate the sudden volume load, and the definitive treatment is emergent surgical aortic valve replacement. An intra-aortic balloon pump is contraindicated in aortic regurgitation because it raises diastolic pressure and worsens regurgitation. Vasodilators and diuretics are only temporizing bridges. Transcatheter replacement is not suitable for acute regurgitation without annular calcification in an unstable patient. Beta-blockers prolong diastole and increase the regurgitant volume, making them harmful here. Vasodilators such as nitroprusside may be used briefly to reduce afterload while the operating room is prepared, but they cannot substitute for valve replacement in acute severe regurgitation with shock.', 'Hard', 97, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 52-year-old man presents with exertional dyspnea and fatigue. Examination reveals a bounding pulse, wide pulse pressure of 160/50 mmHg, and a diastolic decrescendo murmur at the left sternal border. Echocardiography shows severe chronic aortic regurgitation, left ventricular end-diastolic diameter of 68 mm, and left ventricular ejection fraction of 55%. Which of the following is the most appropriate management?', '["Observation with annual echocardiography", "ACE inhibitor and beta-blocker therapy without surgery", "Transcatheter aortic valve replacement", "Surgical aortic valve replacement", "Aortic root replacement with a valve-sparing procedure"]'::jsonb, 3, 'Symptomatic severe chronic aortic regurgitation is an indication for surgical aortic valve replacement. Observation is appropriate only for asymptomatic patients without left ventricular dysfunction or dilation criteria. Medical therapy with vasodilators is an adjunct but does not replace surgery once symptoms develop. Transcatheter replacement is not indicated for native pure aortic regurgitation because there is no calcification to anchor the prosthesis. Valve-sparing root replacement is for aortic root aneurysm with preserved leaflets, not for primary severe regurgitation with a normal root.', 'Medium', 98, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 45-year-old man with a bicuspid aortic valve is found to have severe aortic regurgitation on routine echocardiography. He is asymptomatic and exercises regularly without limitation. Echocardiography shows a left ventricular ejection fraction of 60%, left ventricular end-systolic diameter of 46 mm, and left ventricular end-diastolic diameter of 60 mm. Which of the following is the most appropriate next step?', '["Serial echocardiography every 6-12 months with exercise testing", "Surgical aortic valve replacement now", "Transcatheter aortic valve replacement now", "Start an ACE inhibitor to delay surgery", "Restrict all strenuous physical activity"]'::jsonb, 0, 'This is asymptomatic severe aortic regurgitation with preserved left ventricular function: ejection fraction 60%, end-systolic diameter 46 mm, and end-diastolic diameter 60 mm, all below the surgical thresholds of ejection fraction 55% or less, end-systolic diameter over 50 mm, or end-diastolic diameter over 65 mm. Surveillance with echocardiography every 6-12 months and exercise testing is correct. Valve replacement now is not indicated without symptoms or left ventricular criteria. An ACE inhibitor does not definitively delay surgery, and activity restriction is not required in an asymptomatic patient with preserved function.', 'Medium', 99, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 34-year-old man with a history of intravenous heroin use presents with 2 weeks of fever, chills, and night sweats. He reports injecting drugs daily. Examination shows a temperature of 39.2 C, a new holosystolic murmur at the left lower sternal border, and small painful nodules on his fingertips. Blood cultures grow Staphylococcus aureus in 2 of 2 bottles. Transthoracic echocardiography reveals a 1.2-cm vegetation on the tricuspid valve. Which of the following is the most likely diagnosis?', '["Septic arthritis of the shoulder", "Acute rheumatic fever", "Infective endocarditis", "Libman-Sacks endocarditis", "Nonbacterial thrombotic endocarditis"]'::jsonb, 2, 'This is definite infective endocarditis by the Duke criteria: two major criteria are present, persistent Staphylococcus aureus bacteremia and a vegetation on echocardiography, plus minor criteria including intravenous drug use, fever, Osler nodes, and a new murmur. Septic arthritis does not explain the murmur or vegetation. Acute rheumatic fever follows streptococcal pharyngitis and does not cause Staphylococcus aureus bacteremia. Libman-Sacks endocarditis occurs in systemic lupus erythematosus with sterile vegetations and negative cultures. Nonbacterial thrombotic endocarditis occurs in malignancy or hypercoagulable states, also with sterile vegetations and negative cultures.', 'Easy', 100, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 71-year-old woman presents with fever and fatigue 3 months after mechanical aortic valve replacement. Blood cultures grow coagulase-negative staphylococci in multiple bottles. Transesophageal echocardiography shows a vegetation on the prosthetic valve with a perivalvular abscess. Which of the following organisms is most commonly responsible for prosthetic valve endocarditis in the early postoperative period?', '["Streptococcus viridans", "Enterococcus faecalis", "HACEK organisms", "Candida albicans", "Staphylococcus epidermidis"]'::jsonb, 4, 'Early prosthetic valve endocarditis, within 12 months of surgery and especially within 2 months, is most often caused by coagulase-negative staphylococci such as Staphylococcus epidermidis, introduced during perioperative contamination; Staphylococcus aureus is also common. Viridans streptococci typically cause native valve endocarditis and late prosthetic valve infection. Enterococcus is more common in older men after genitourinary or gastrointestinal procedures and in late prosthetic valve infection. HACEK organisms cause subacute native valve endocarditis with slow-growing cultures. Candida causes fungal endocarditis mainly in intravenous drug users or prosthetic valve patients but is uncommon.', 'Medium', 101, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 62-year-old man with aortic valve infective endocarditis is on day 10 of intravenous antibiotics. He develops worsening dyspnea and pulmonary edema. Echocardiography shows severe aortic regurgitation from a perforated aortic leaflet, a 12-mm mobile vegetation, and a left ventricular ejection fraction of 45%. He had one embolic stroke 3 days ago. Blood cultures remain positive for Staphylococcus aureus. Which of the following is the most appropriate next step in management?', '["Continue intravenous antibiotics alone for 6 weeks", "Urgent surgical aortic valve replacement", "Add rifampin and gentamicin to the antibiotic regimen", "Anticoagulation with intravenous heparin", "Discharge to complete antibiotics as an outpatient"]'::jsonb, 1, 'Surgery is indicated for infective endocarditis with heart failure from valve dysfunction, persistent bacteremia, and a large vegetation with embolic events. Antibiotics alone cannot repair a perforated leaflet with severe regurgitation. Adding antibiotics does not address the mechanical failure. Anticoagulation is not indicated and increases the risk of hemorrhagic conversion after an embolic stroke. Outpatient completion is inappropriate in an unstable patient with ongoing infection and heart failure. Guidelines also recommend surgery for perivalvular abscess, persistent bacteremia beyond 5-7 days of appropriate antibiotics, and prosthetic valve infection with dehiscence; in this patient the combination of heart failure, large vegetation, and embolic events makes the indication clear.', 'Hard', 102, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 29-year-old man presents with 2 days of sharp chest pain that worsens when lying flat and improves when sitting forward. He had a viral upper respiratory illness last week. Examination reveals a pericardial friction rub. Electrocardiography shows diffuse concave ST-segment elevations with PR-segment depression. Troponin is mildly elevated and echocardiography shows a small pericardial effusion without tamponade physiology. Which of the following is the most appropriate treatment?', '["Intravenous heparin and urgent coronary angiography", "High-dose corticosteroids", "Empiric broad-spectrum antibiotics", "Nonsteroidal anti-inflammatory drug plus colchicine", "Pericardiocentesis"]'::jsonb, 3, 'This is acute viral pericarditis: positional pleuritic pain, friction rub, and diffuse concave ST elevations with PR depression. A nonsteroidal anti-inflammatory drug plus colchicine for 3 months is first-line therapy and reduces recurrence. The mildly elevated troponin reflects epicardial inflammation, not acute coronary syndrome, so heparin and angiography are not indicated. Corticosteroids are reserved for refractory cases or specific causes because they increase recurrence. Antibiotics are for purulent pericarditis, not viral disease. Pericardiocentesis is for tamponade or diagnostic sampling, not uncomplicated pericarditis.', 'Medium', 103, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 58-year-old woman with metastatic breast cancer presents with progressive dyspnea, fatigue, and lightheadedness. Her blood pressure is 92/64 mmHg with a heart rate of 118/min. Examination reveals markedly elevated jugular venous pressure, muffled heart sounds, and a paradoxical pulse with an inspiratory systolic blood pressure fall of 18 mmHg. Electrocardiography shows low voltage and electrical alternans. Echocardiography shows a large pericardial effusion with diastolic collapse of the right atrium and right ventricle. Which of the following is the most appropriate next step in management?', '["Emergent pericardiocentesis", "Intravenous loop diuretic", "Surgical pericardiectomy", "Intravenous fluids alone and observation", "Thoracentesis"]'::jsonb, 0, 'Beck triad of hypotension, jugular venous distension, and muffled heart sounds, plus pulsus paradoxus over 10 mmHg and echocardiographic diastolic collapse of the right atrium and ventricle, establishes cardiac tamponade. Emergent pericardiocentesis is the definitive treatment. Diuretics reduce preload and worsen tamponade. Surgical pericardiectomy is for constrictive pericarditis, not acute tamponade. Intravenous fluids are only a temporizing bridge. Thoracentesis addresses pleural effusion, not pericardial tamponade. Intravenous fluids can transiently support blood pressure by increasing preload, but this is only a bridge and must not delay drainage. Pericardiocentesis relieves the elevated intrapericardial pressure and restores cardiac output, and the fluid should be sent for analysis to identify the cause.', 'Medium', 104, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 63-year-old man with a history of tuberculous pericarditis presents with progressive peripheral edema, ascites, and exertional dyspnea. Examination reveals elevated jugular venous pressure that rises with inspiration (Kussmaul sign), a pericardial knock, and hepatomegaly. Echocardiography shows a thickened pericardium, septal bounce, and exaggerated respiratory variation in mitral inflow velocities. Cardiac catheterization shows equalization of diastolic pressures in all chambers with a dip-and-plateau pattern. Which of the following is the most appropriate definitive treatment?', '["Long-term high-dose loop diuretics", "Heart transplantation", "Surgical pericardiectomy", "Pericardiocentesis", "High-dose corticosteroids"]'::jsonb, 2, 'Constrictive pericarditis is diagnosed by the Kussmaul sign, pericardial knock, equalization of diastolic pressures, and the dip-and-plateau (square root) sign, with septal bounce on echocardiography. The definitive treatment is surgical pericardiectomy to remove the rigid pericardium. Diuretics only temporize symptoms. Heart transplantation is for end-stage restrictive cardiomyopathy, not constriction. Pericardiocentesis treats effusion and tamponade, not a thickened rigid pericardium. Corticosteroids help acute pericarditis but not established constriction. Diuretics may relieve congestion temporarily but do not correct the impaired diastolic filling, and constrictive pericarditis must be distinguished from restrictive cardiomyopathy, where pericardiectomy would not help and management is medical.', 'Hard', 105, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 54-year-old woman with a history of hypertension presents with abrupt-onset severe chest pain radiating to her back and neck. Her blood pressure is 185/105 mmHg in the right arm and 160/95 mmHg in the left arm. Examination reveals a diastolic decrescendo murmur and a widened mediastinum on chest radiography. CT angiography shows an intimal flap in the ascending aorta with involvement of the aortic arch. Which of the following is the most appropriate definitive management?', '["Intravenous labetalol infusion alone with close monitoring", "Intravenous heparin anticoagulation", "Thrombolytic therapy", "CT angiography of the abdomen to assess extent", "Emergent surgical repair of the ascending aorta"]'::jsonb, 4, 'This is a Stanford type A aortic dissection involving the ascending aorta, which requires emergent surgical repair; medical therapy alone carries a very high mortality. Blood pressure and heart rate control with esmolol or labetalol is given while preparing for surgery, not as sole treatment. Heparin and thrombolytics are contraindicated because they increase the risk of rupture and extension of the dissection. The diagnosis is already confirmed by CT angiography, so further imaging only delays life-saving surgery. Preoperative blood pressure and heart rate control with an intravenous beta-blocker reduces aortic wall stress while the surgical team prepares, but it must never substitute for definitive repair in type A dissection.', 'Medium', 106, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 67-year-old man with poorly controlled hypertension presents with sudden severe tearing pain in his mid-back. His blood pressure is 205/125 mmHg and heart rate is 108/min. CT angiography shows an intimal flap beginning just distal to the left subclavian artery with no evidence of rupture, malperfusion, or aortic expansion. Which of the following is the most appropriate initial management?', '["Sodium nitroprusside infusion alone", "Intravenous esmolol to lower heart rate, followed by sodium nitroprusside", "Emergent open surgical repair", "Intravenous heparin", "Oral metoprolol and outpatient follow-up"]'::jsonb, 1, 'This is an uncomplicated Stanford type B dissection, which is managed medically by reducing heart rate below 60 and systolic blood pressure to 100-120 mmHg to decrease aortic wall shear stress. Beta-blockade with esmolol must precede vasodilator therapy, because nitroprusside alone causes reflex tachycardia and increased dP/dt, worsening the dissection. Open surgery is reserved for type A dissection or complicated type B disease. Heparin is contraindicated in dissection. Oral therapy and outpatient care are inadequate for an acute dissection. After heart rate and blood pressure targets are achieved, the patient needs intensive care monitoring with serial imaging, and any sign of malperfusion, rupture, or expansion changes management to endovascular or surgical intervention.', 'Medium', 107, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 72-year-old man with a known Stanford type B aortic dissection is admitted for medical management. Despite intravenous antihypertensive therapy, he develops worsening abdominal pain, rising serum creatinine, and oliguria. Repeat CT angiography shows the dissection flap has extended with compromise of the left renal artery and a rapidly expanding false lumen. Which of the following is the most appropriate next step in management?', '["Continue medical therapy and add a second antihypertensive agent", "Open surgical repair of the descending aorta", "Intravenous thrombolytic therapy", "Thoracic endovascular aortic repair (TEVAR)", "Renal artery angioplasty alone"]'::jsonb, 3, 'This is a complicated type B dissection with malperfusion (renal ischemia) and a rapidly expanding false lumen, which requires intervention. Thoracic endovascular aortic repair is preferred: the stent-graft covers the entry tear, re-expands the true lumen, and restores branch perfusion with lower morbidity than open surgery. Continuing medical therapy alone fails when malperfusion is present. Open repair is reserved for anatomy unsuitable for endovascular repair. Thrombolytics are contraindicated in dissection. Renal artery angioplasty alone does not address the dissection. Endovascular repair works by covering the primary entry tear, which depressurizes the false lumen and re-expands the true lumen, restoring perfusion to compromised branches; this is now the standard approach for complicated type B dissection when anatomy is suitable.', 'Hard', 108, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 68-year-old man with a 35 pack-year smoking history presents for a routine health visit. He has no abdominal pain, back pain, or claudication. His blood pressure is 138/82 mmHg. Physical examination is unremarkable with no palpable abdominal mass. He has never had abdominal imaging. Which of the following screening tests is most appropriate?', '["One-time abdominal ultrasonography", "CT angiography of the abdomen", "Annual abdominal ultrasonography", "No screening is indicated", "Magnetic resonance angiography of the abdomen"]'::jsonb, 0, 'The US Preventive Services Task Force recommends one-time abdominal ultrasound screening for abdominal aortic aneurysm in men aged 65-75 years who have ever smoked. CT angiography and magnetic resonance angiography are not screening tests because of radiation, contrast, and cost, and are reserved for diagnosis and surgical planning. Annual ultrasound is used for surveillance of a known small aneurysm, not for screening. No screening would be incorrect because this patient meets the screening criteria. If an aneurysm is found, surveillance intervals depend on size, with repair generally recommended at 5.5 cm or more in men; screening also provides an opportunity to address smoking cessation and cardiovascular risk reduction.', 'Easy', 109, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 73-year-old man with a known abdominal aortic aneurysm presents for follow-up. He is asymptomatic. Serial imaging shows the aneurysm has grown from 5.1 cm to 5.6 cm over the past year. He has well-controlled hypertension and no significant cardiopulmonary disease. Which of the following is the most appropriate management?', '["Continue surveillance with ultrasound every 6 months", "Start a beta-blocker and an ACE inhibitor to slow expansion", "Elective endovascular aneurysm repair (EVAR)", "Emergent open surgical repair", "Start high-dose statin therapy and repeat imaging in 2 years"]'::jsonb, 2, 'Elective repair of an abdominal aortic aneurysm is indicated at 5.5 cm or more in men, or with rapid expansion of 0.5 cm or more in 6 months; at 5.6 cm with growth, surveillance is no longer appropriate. Endovascular repair is preferred in suitable anatomy and older patients, with open repair as an alternative. Medical therapy with beta-blockers, ACE inhibitors, or statins does not prevent expansion or rupture. Emergent repair is for rupture or symptomatic aneurysm, not for an elective indication.', 'Medium', 110, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 32-year-old man with Marfan syndrome presents for routine cardiology follow-up. He is asymptomatic. Echocardiography shows an ascending aortic root diameter of 5.0 cm, unchanged from 4.8 cm one year ago. He has no aortic regurgitation and no family history of aortic dissection. He is currently taking atenolol. Which of the following is the most appropriate management?', '["Continue beta-blocker therapy and repeat imaging in 2 years", "Switch from atenolol to an angiotensin receptor blocker alone", "Annual echocardiography without surgical referral", "Transcatheter aortic valve replacement", "Referral for elective surgical repair of the ascending aorta"]'::jsonb, 4, 'In Marfan syndrome, elective repair of the ascending aorta is recommended at 5.0 cm or more, or at 4.5 cm or more with risk factors such as family history of dissection, growth of 0.3 cm per year or more, or significant aortic regurgitation. At 5.0 cm this patient meets the threshold. Beta-blockers and angiotensin receptor blockers slow aortic growth but do not replace surgery once the threshold is reached. Surveillance alone is inadequate at this diameter. Transcatheter valve replacement addresses valve disease, not an aortic aneurysm.', 'Hard', 111, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 56-year-old woman is found to have blood pressure of 148/92 mmHg on two separate office visits. She has no history of hypertension, diabetes, or kidney disease. Her home blood pressure readings average 132/84 mmHg, and her physical examination and basic laboratory studies are normal. Which of the following is the most appropriate next step?', '["Start a thiazide diuretic immediately", "Confirm with 24-hour ambulatory blood pressure monitoring and recommend lifestyle modification", "Start an ACE inhibitor and a calcium channel blocker", "Diagnose stage 2 hypertension and start a beta-blocker", "No further evaluation is needed; reassure and discharge"]'::jsonb, 1, 'Office blood pressure is elevated but home readings are lower, suggesting white coat hypertension. Confirmation with 24-hour ambulatory blood pressure monitoring is required before labeling or treating her, followed by lifestyle modification and periodic monitoring. Starting antihypertensives based on office readings alone risks overtreatment. Beta-blockers are not first-line therapy for uncomplicated hypertension. Simple reassurance without confirmation would miss masked hypertension and the need for follow-up, since white coat hypertension can progress. Ambulatory monitoring also detects masked hypertension, in which office readings are normal but out-of-office readings are elevated; patients with confirmed white coat hypertension need regular re-evaluation because a substantial proportion develops sustained hypertension over time.', 'Medium', 112, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 61-year-old man with type 2 diabetes mellitus and hypertension presents for follow-up. His blood pressure is 152/94 mmHg despite a low-sodium diet. Laboratory studies show a serum creatinine of 1.3 mg/dL and a urine albumin-to-creatinine ratio of 420 mg/g. He takes metformin and atorvastatin. Which of the following antihypertensive agents is most appropriate to add?', '["Amlodipine", "Hydrochlorothiazide", "Atenolol", "Lisinopril", "Hydralazine"]'::jsonb, 3, 'Diabetes with albuminuria above 300 mg/g is an indication for an ACE inhibitor or angiotensin receptor blocker as first-line therapy, because these agents lower blood pressure and reduce albuminuria and progression of chronic kidney disease. Amlodipine and hydrochlorothiazide lower blood pressure but lack the same renoprotective antiproteinuric effect. Atenolol is not first-line therapy for hypertension and has inferior outcomes. Hydralazine is reserved for resistant hypertension or specific indications such as heart failure with reduced ejection fraction in combination with isosorbide dinitrate.', 'Medium', 113, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 59-year-old man with a history of untreated hypertension presents with severe headache, confusion, and blurred vision. His blood pressure is 214/132 mmHg and heart rate is 96/min. Examination reveals papilledema and bilateral retinal hemorrhages. Laboratory studies show a serum creatinine of 2.1 mg/dL (baseline 1.0) and 2+ protein on urinalysis. CT of the head shows no hemorrhage or infarction. Which of the following is the most appropriate management?', '["Admit to the intensive care unit and start intravenous nicardipine", "Give sublingual nifedipine to lower blood pressure rapidly", "Start oral clonidine and discharge home with close follow-up", "Give intravenous nitroprusside as the first-line agent", "Observe without treatment until blood pressure falls spontaneously"]'::jsonb, 0, 'This is a hypertensive emergency: blood pressure above 180/120 mmHg with acute target-organ damage including encephalopathy, acute kidney injury, and retinopathy. It requires intensive care admission and intravenous antihypertensives such as nicardipine, labetalol, or clevidipine, with a controlled reduction of about 25% of mean arterial pressure in the first hour. Sublingual nifedipine causes precipitous unpredictable drops and is contraindicated. Oral therapy and discharge are for hypertensive urgency, which has no acute organ damage. Nitroprusside is no longer first-line because of cyanide toxicity and the need for an arterial line. Observation risks progression of organ damage.', 'Hard', 114, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 62-year-old man with a 20 pack-year smoking history presents for a routine visit. He has no history of cardiovascular disease or diabetes. His blood pressure is 138/84 mmHg, total cholesterol is 248 mg/dL, LDL cholesterol is 165 mg/dL, and HDL cholesterol is 40 mg/dL. His calculated 10-year atherosclerotic cardiovascular disease risk is 21%. Which of the following is the most appropriate therapy?', '["Lifestyle modification alone without medication", "Moderate-intensity statin therapy", "High-intensity statin therapy (atorvastatin 40-80 mg)", "Ezetimibe monotherapy", "Niacin plus a fibrate"]'::jsonb, 2, 'A 10-year atherosclerotic cardiovascular disease risk of 20% or more warrants high-intensity statin therapy with atorvastatin 40-80 mg or rosuvastatin 20-40 mg. Moderate-intensity statin is for intermediate risk of 7.5% to under 20%. Lifestyle modification alone is insufficient at this level of risk. Ezetimibe monotherapy has limited outcome data and is not first-line therapy. Niacin and fibrates do not reduce cardiovascular events and are not substitutes for a statin. The high-intensity statin should be started together with lifestyle changes including smoking cessation, a heart-healthy diet, and regular exercise, with a lipid panel rechecked in 4-12 weeks to confirm an LDL reduction of at least 50%.', 'Medium', 115, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 63-year-old woman with type 2 diabetes mellitus for 8 years is taking atorvastatin 20 mg daily. Her LDL cholesterol is 98 mg/dL and she has no history of cardiovascular disease. Her blood pressure is 132/78 mmHg and her hemoglobin A1c is 7.2%. Which of the following is the most appropriate change to her lipid therapy?', '["Stop the statin because her LDL is below 100 mg/dL", "Add ezetimibe to the current statin dose", "Add a PCSK9 inhibitor", "Switch to a fibrate", "Increase atorvastatin to 40-80 mg daily"]'::jsonb, 4, 'Adults aged 40-75 years with diabetes and LDL cholesterol of 70 mg/dL or more should receive high-intensity statin therapy with atorvastatin 40-80 mg, regardless of calculated risk. Her LDL of 98 mg/dL on moderate-intensity statin means the dose should be intensified. Stopping the statin is wrong because diabetes is a major cardiovascular risk factor. Ezetimibe is added only after maximally tolerated statin therapy if LDL remains 70 mg/dL or more in secondary prevention. PCSK9 inhibitors are for familial hypercholesterolemia or secondary prevention with LDL 70 mg/dL or more on maximal therapy. Fibrates are for severe hypertriglyceridemia, not LDL lowering.', 'Medium', 116, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 67-year-old man had a myocardial infarction 3 months ago and is taking atorvastatin 80 mg daily, aspirin, and a beta-blocker. His LDL cholesterol is 112 mg/dL, down from 150 mg/dL before the event. He has no muscle symptoms. Which of the following is the most appropriate next step in his lipid management?', '["Continue atorvastatin 80 mg without change", "Add ezetimibe", "Add a PCSK9 inhibitor now", "Switch atorvastatin to rosuvastatin 40 mg", "Add niacin"]'::jsonb, 1, 'In secondary prevention after acute coronary syndrome, a patient on maximally tolerated high-intensity statin with LDL cholesterol of 70 mg/dL or more should first add ezetimibe, which showed outcome benefit in the IMPROVE-IT trial. If LDL remains 70 mg/dL or more, a PCSK9 inhibitor is then added, so it is second-line rather than first. Continuing without change leaves LDL above the goal of under 70 mg/dL. Switching statins adds no further LDL lowering beyond the maximum dose. Niacin has no outcome benefit and causes harm.', 'Medium', 117, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 36-year-old woman presents with progressive exertional dyspnea and fatigue. Examination reveals a fixed split second heart sound, a systolic ejection murmur at the left upper sternal border, and a right ventricular heave. Electrocardiography shows right bundle branch block and right axis deviation. Echocardiography shows a 1.8-cm secundum atrial septal defect with right atrial and right ventricular enlargement and a Qp:Qs ratio of 2.1. There is no pulmonary hypertension. Which of the following is the most appropriate management?', '["Observation with annual echocardiography", "Surgical closure of the defect", "Medical therapy with a diuretic and an ACE inhibitor", "Transcatheter device closure of the defect", "Anticoagulation with warfarin"]'::jsonb, 3, 'A secundum atrial septal defect with a Qp:Qs ratio of 1.5 or more and right ventricular volume overload should be closed, and transcatheter device closure is preferred for suitable secundum defects. Observation is appropriate only for small defects without right ventricular enlargement. Surgical closure is reserved for primum defects, sinus venosus defects, or large defects unsuitable for a device. Medical therapy does not close the defect. Anticoagulation is not indicated without atrial fibrillation or thrombus. Closure is also recommended in patients with paradoxical embolism or platypnea-orthodeoxia, and after closure the patient needs follow-up echocardiography to confirm device position and exclude residual shunt or erosion.', 'Medium', 118, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 27-year-old man presents with headaches and is found to have blood pressure of 172/102 mmHg in his right arm. His femoral pulses are weak and delayed compared with his radial pulses, and blood pressure in his legs is 118/76 mmHg. Chest radiography shows notching of the inferior borders of the ribs and a figure-3 sign. Which of the following is the most likely diagnosis?', '["Essential hypertension", "Renal artery stenosis", "Coarctation of the aorta", "Pheochromocytoma", "Aortic dissection"]'::jsonb, 2, 'Upper-extremity hypertension with weak and delayed femoral pulses, a radiofemoral delay, an arm-leg blood pressure gradient, and rib notching from collateral circulation is classic for coarctation of the aorta. Essential hypertension does not cause a blood pressure gradient between the arms and legs or rib notching. Renal artery stenosis causes hypertension with an abdominal bruit and asymmetric kidneys, not pulse delay. Pheochromocytoma causes episodic hypertension with headache, palpitations, and sweating. Aortic dissection causes acute severe tearing pain rather than chronic hypertension with rib notching.', 'Easy', 119, 'MCQ'),
('f5032e67-7e04-444f-a02f-a448415463f2', 'A 30-year-old man is found to have a holosystolic murmur at the left lower sternal border during a routine examination. He is asymptomatic and exercises regularly. Echocardiography shows a small restrictive muscular ventricular septal defect with a Qp:Qs ratio of 1.2, normal right ventricular size, and no pulmonary hypertension. Which of the following is the most appropriate management?', '["Observation with periodic echocardiography", "Surgical closure of the defect", "Transcatheter device closure of the defect", "Antibiotic prophylaxis before all dental procedures", "Restriction of all strenuous exercise"]'::jsonb, 0, 'A small restrictive ventricular septal defect with a Qp:Qs ratio under 1.5, no symptoms, no chamber enlargement, and no pulmonary hypertension is managed with observation and periodic echocardiography. Closure, surgical or transcatheter, is indicated for a significant left-to-right shunt with a Qp:Qs ratio of 1.5 or more with left ventricular volume overload or pulmonary hypertension. Antibiotic prophylaxis is not recommended for an unrepaired simple ventricular septal defect; it is reserved for prosthetic material, prior endocarditis, unrepaired cyanotic heart disease, or repaired defects with residual lesions. Exercise restriction is unnecessary.', 'Medium', 120, 'MCQ');
